    async def _pm_sync_upsert_items(self, items: list) -> None:
        """Idempotent upsert into work_items keyed by (repo, number, kind).

        Also the BIRTH of an auto-filed error report's ``evidence`` hold (spec
        2026-09-18 §5): an ``auto-error`` issue is a stack trace, not a diagnosis,
        so it enters the mirror already parked for investigation instead of
        falling into the queue as ordinary work. This is the only seam that can
        write it — it is the one place that knows a row is NEW; a tick that
        re-held an existing row would undo the very investigation that cleared
        the hold, so the write lives strictly on the new-row branch.
        """
        from datetime import datetime, timezone
        from sqlalchemy import select
        from server.audit import record_audit
        from server.automations.error_triage import LABEL as AUTO_ERROR_LABEL
        from server.db.models import WorkItem
        from server.pm.holds import (
            ERROR_TRIAGE_ACTOR, EVIDENCE_BIRTH_REASON, actor_class, set_evidence_hold,
        )
        async with db_session() as db:
            born_held: list[WorkItem] = []
            for item in items:
                existing = (await db.execute(
                    select(WorkItem).where(
                        WorkItem.repo == item.repo,
                        WorkItem.number == item.number,
                        WorkItem.kind == item.kind,
                    )
                )).scalar_one_or_none()
                now = datetime.now(timezone.utc)
                is_new = existing is None
                if existing is None:
                    existing = WorkItem(repo=item.repo, number=item.number,
                                       kind=item.kind)
                    db.add(existing)
                existing.title = item.title
                existing.body = item.body
                existing.state = item.state
                existing.labels = list(item.labels)
                existing.author = item.author
                existing.url = item.url
                existing.linked_issue_numbers = list(item.linked_issue_numbers)
                existing.assignees = list(item.assignees)
                existing.gh_node_id = item.node_id or existing.gh_node_id
                existing.gh_created_at = item.gh_created_at
                existing.gh_updated_at = item.gh_updated_at
                existing.gh_closed_at = item.gh_closed_at
                existing.last_synced_at = now
                if (is_new and item.kind == "issue" and item.state == "open"
                        and AUTO_ERROR_LABEL in (item.labels or ())):
                    # After the field copy on purpose: set_hold fingerprints
                    # title/body, and the fingerprint is what makes a later body
                    # edit a release signal for this hold.
                    set_evidence_hold(existing, reason=EVIDENCE_BIRTH_REASON,
                                      actor=ERROR_TRIAGE_ACTOR, now=now)
                    born_held.append(existing)
            if born_held:
                # ``WorkItem.id`` is a Python-side default, so it exists only once
                # the INSERT is flushed — and the audit row must name it.
                await db.flush()
                for wi in born_held:
                    await record_audit(db=db, type="pm.hold.set",
                                       identity=ERROR_TRIAGE_ACTOR, via="pm_sync",
                                       detail={"workItemId": wi.id, "kind": "evidence",
                                               "reason": EVIDENCE_BIRTH_REASON,
                                               "actorClass": actor_class(ERROR_TRIAGE_ACTOR)})

    async def _pm_sync_save_state(self, view, **updates) -> None:
        """Map keyword updates onto the ProjectRepo row for *view*."""
        from sqlalchemy import select
        from server.db.models import ProjectRepo
        async with db_session() as db:
            row = (await db.execute(
                select(ProjectRepo).where(
                    ProjectRepo.project_id == view.project_id,
                    ProjectRepo.repo == view.repo,
                )
            )).scalar_one_or_none()
            if row is None:
                return
            for key, value in updates.items():
                setattr(row, key, value)

    async def _pm_sync_read_feature_docs(
        self, repo: str, ref: str | None = None
    ) -> "FeatureDocsRead":
        """Read docs/product/features/*.md at *ref* (default: origin's default
        branch) in the shared clone. Uses git plumbing only — no GitHub API cost.

        ATOMIC-OR-RAISE for the default-branch read (``ref is None``): it
        resolves the branch to an IMMUTABLE commit SHA once, then reads every
        blob against THAT snapshot — so a concurrent fetch moving
        origin/master (the shared clone is touched by many automations) can't
        make the per-doc reads race. Any failure — clone, ref resolution,
        ls-tree, or a single unreadable blob — RAISES rather than returning a
        subset. Returning a subset is what orphaned 21 live features in the
        dogfood: the caller (``_feature_index``) treats a missing doc as
        deleted and orphans its row. A raise makes the caller skip the pass
        instead, leaving the index untouched until a clean read.

        A caller-supplied *ref* is a map-changes branch name (R8b-4), resolved
        as ``refs/remotes/origin/<ref>``. ``git fetch origin`` above already
        fetches every remote branch, so the ref resolves once that has run. A
        branch that does not exist on the remote raises here too — the caller
        (``_feature_index``) treats this read as best-effort and does not let
        it poison the default-branch plan."""
        from server.pm.feature_index import FeatureDocsRead

        async def _read() -> FeatureDocsRead:
            import subprocess
            repo_root = await self._effective_repo_root()
            url = f"https://github.com/{repo}.git"
            # A clone failure must NOT degrade to an empty list — that would
            # orphan every indexed feature. Let it raise so the pass is skipped.
            clone = await asyncio.to_thread(
                gitrepos.ensure_clone, repo_root, repo, url)
            await asyncio.to_thread(
                subprocess.run,
                ["git", "-C", clone, "fetch", "origin", "--quiet"],
                check=False, capture_output=True, timeout=120,
            )
            if ref is not None:
                resolved_ref = f"refs/remotes/origin/{ref}"
            else:
                head = await asyncio.to_thread(
                    subprocess.run,
                    ["git", "-C", clone, "symbolic-ref", "--quiet",
                     "refs/remotes/origin/HEAD"],
                    capture_output=True, text=True, timeout=30,
                )
                resolved_ref = head.stdout.strip() or "refs/remotes/origin/master"
            # Pin the ref to a concrete commit so every blob read below is against
            # one consistent snapshot, immune to a concurrent ref-moving fetch.
            rp = await asyncio.to_thread(
                subprocess.run,
                ["git", "-C", clone, "rev-parse", "--verify", f"{resolved_ref}^{{commit}}"],
                capture_output=True, text=True, timeout=30,
            )
            if rp.returncode != 0:
                raise RuntimeError(
                    f"pm_sync.read_feature_docs: cannot resolve {resolved_ref} in "
                    f"{repo}: {(rp.stderr or '').strip()[:200]}")
            sha = rp.stdout.strip()
            ls = await asyncio.to_thread(
                subprocess.run,
                ["git", "-C", clone, "ls-tree", "-r", "--name-only", sha,
                 "docs/product/features/"],
                capture_output=True, text=True, timeout=30,
            )
            if ls.returncode != 0:
                raise RuntimeError(
                    f"pm_sync.read_feature_docs: ls-tree failed for {repo}: "
                    f"{(ls.stderr or '').strip()[:200]}")
            out: list[tuple[str, str]] = []
            for path in ls.stdout.splitlines():
                if not path.endswith(".md"):
                    continue
                show = await asyncio.to_thread(
                    subprocess.run,
                    ["git", "-C", clone, "show", f"{sha}:{path}"],
                    capture_output=True, text=True, timeout=30,
                )
                if show.returncode != 0:
                    # One unreadable blob makes the whole read untrustworthy —
                    # raise so the caller skips rather than orphaning the rest.
                    raise RuntimeError(
                        f"pm_sync.read_feature_docs: read failed for {path} in "
                        f"{repo}: {(show.stderr or '').strip()[:200]}")
                out.append((path, show.stdout))
            return FeatureDocsRead(sha=sha, docs=out)

        return await _read()

    async def _pm_sync_resolve_evidence_paths(
        self, repo: str, sha: str, paths: list[str], timed: set[str],
    ) -> "dict[str, PathResolution]":
        """Resolve feature-doc evidence paths against the tree at *sha* (#2162)
        in the shared clone ``_pm_sync_read_feature_docs`` just fetched: one
        ``ls-tree`` for existence (matching rules in ``server/pm/evidence.py``),
        plus one ``git log -1`` per present path in *timed*. The answer is a pure
        function of its inputs, so it is cached per repo and only recomputed
        when the default branch (or the cited set) moves — the pm-sync tick is
        frequent and most ticks see an unchanged head."""
        from datetime import datetime, timezone

        from server.pm.evidence import PathResolution, matches

        key = (sha, tuple(sorted(paths)), tuple(sorted(timed)))
        cached = self._pm_evidence_cache.get(repo)
        if cached is not None and cached[0] == key:
            return cached[1]

        def _resolve() -> "dict[str, PathResolution]":
            import subprocess
            clone = gitrepos.ensure_clone(
                repo_root, repo, f"https://github.com/{repo}.git")
            ls = subprocess.run(
                ["git", "-C", clone, "ls-tree", "-r", "-z", "--name-only", sha],
                capture_output=True, text=True, timeout=60)
            if ls.returncode != 0:
                raise RuntimeError(
                    f"pm_sync.resolve_evidence_paths: ls-tree failed for {repo}: "
                    f"{(ls.stderr or '').strip()[:200]}")
            tree = [p for p in ls.stdout.split("\0") if p]
            out: dict[str, PathResolution] = {}
            for path in paths:
                exists = bool(matches(path, tree))
                when: datetime | None = None
                if exists and path in timed:
                    # `:(top)` pins the pathspec to the repo root and keeps a
                    # path that starts with `:` from being read as magic.
                    lg = subprocess.run(
                        ["git", "-C", clone, "log", "-1", "--format=%ct", sha,
                         "--", f":(top){path}"],
                        capture_output=True, text=True, timeout=30)
                    stamp = lg.stdout.strip() if lg.returncode == 0 else ""
                    if stamp.isdigit():
                        when = datetime.fromtimestamp(int(stamp), tz=timezone.utc)
                out[path] = PathResolution(exists=exists, last_commit_at=when)
            return out

        repo_root = await self._effective_repo_root()
        result = await asyncio.to_thread(_resolve)
        self._pm_evidence_cache[repo] = (key, result)
        return result

    _PM_SYNC_CONSTITUTION_PATH = ".specify/memory/constitution.md"

    async def _pm_sync_read_constitution(
        self, repo: str, ref: str | None = None
    ) -> str | None:
        """Read `.specify/memory/constitution.md` at *ref* (default: origin's
        default branch) in the shared clone — same git-plumbing-only approach as
        `_pm_sync_read_feature_docs`, but single-file and best-effort: unlike that
        reader's atomic-or-raise contract (a partial feature-doc read would orphan
        capabilities), a repo with NO constitution at all is the expected common
        case for issue #2165, not a read failure — this returns None rather than
        raising."""
        import subprocess

        async def _read() -> str | None:
            repo_root = await self._effective_repo_root()
            url = f"https://github.com/{repo}.git"
            clone = await asyncio.to_thread(
                gitrepos.ensure_clone, repo_root, repo, url)
            await asyncio.to_thread(
                subprocess.run,
                ["git", "-C", clone, "fetch", "origin", "--quiet"],
                check=False, capture_output=True, timeout=120,
            )
            if ref is not None:
                resolved_ref = f"refs/remotes/origin/{ref}"
            else:
                head = await asyncio.to_thread(
                    subprocess.run,
                    ["git", "-C", clone, "symbolic-ref", "--quiet",
                     "refs/remotes/origin/HEAD"],
                    capture_output=True, text=True, timeout=30,
                )
                resolved_ref = head.stdout.strip() or "refs/remotes/origin/master"
            show = await asyncio.to_thread(
                subprocess.run,
                ["git", "-C", clone, "show",
                 f"{resolved_ref}:{self._PM_SYNC_CONSTITUTION_PATH}"],
                capture_output=True, text=True, timeout=30,
            )
            if show.returncode != 0:
                return None
            return show.stdout

        return await _read()

    async def _pm_sync_save_constitution_status(
        self, project_id: str, status: str | None,
    ) -> None:
        """Persist this pass's constitution governance status onto the project
        row (issue #2165) — see server/pm/mirror_store.py:set_project_constitution_status."""
        from server.pm import mirror_store
