    async def _pm_sync_tick_loop(self, interval: float) -> None:
        """Periodic driver for the pm-sync control loop (mirrors _sdlc_intake_tick_loop)."""
        while True:
            await self._pm_sync_tick_once()
            await asyncio.sleep(interval)

    async def _pm_sync_tick_once(self) -> None:
        """One pm-sync tick + an enabled-only ``last_active_at`` heartbeat.
        Best-effort — neither the tick nor the heartbeat may crash the loop."""
        # Accepted manual GitHub effects outlive open map pointers and policy
        # changes. Observe them without authorizing or replaying any new work.
        try:
            await self.pm_map_changes().reconcile_updates()
        except Exception:
            log.warning("pm_sync.map_recovery_observation_failed", exc_info=True)
        if not await self._schedule_allows_tick("pm-sync"):
            return
        try:
            await self._pm_sync_loop.tick()
        except Exception:  # pragma: no cover — tick() already swallows; belt+braces
            log.warning("pm_sync.tick_loop_error", exc_info=True)
        try:
            mode, _ = await self._pm_sync_read_config()
            if mode != "off":
                await self._bump_automation_active("pm-sync")
        except Exception:  # pragma: no cover — a heartbeat failure must not stall
            log.debug("pm_sync.bump_active_failed", exc_info=True)

    # ------------------------------------------------------------------
    # PM Triage control-loop dependencies (injected into PmTriageLoop, design §6)
    #
    # Every seam is a thin adapter over db_session() or an EXISTING phase-2 seam.
    # There is no classify path and no map-synthesis path here: classify is
    # ``pm_classify_run(slug, items=…)`` and drift is
    # ``pm_onboard_spawn_map(slug, scope="diff", …)``.
    # ------------------------------------------------------------------

    async def _pm_triage_read_config(self) -> tuple[str, dict]:
        """The pm-triage row's (mode, config) merged onto schema defaults.

        Mirrors ``_pm_sync_read_config``: mode is ``off`` unless the row is
        enabled AND carries ``propose`` — an absent/invalid row falls back to
        ``off`` + pure defaults, so a bad config never proposes anything. There is
        deliberately no ``auto`` mode (design §6)."""
        from server.automations.config_store import read_automation_config
        from server.automations.pm_triage import PmTriage
        return await read_automation_config(
            PmTriage, modes=("propose",),
            log_key="pm_triage")

    @staticmethod
    def _classifiable_hold_clause():
        """THE hold half of the classify-candidate predicate, shared by
        ``_pm_triage_list_pending`` and ``_pm_triage_count_state`` so the list and the
        count can never disagree about who is a candidate.

        Only ``HELD_KINDS`` (``owner_action`` / ``decision``) disqualify an item. Those
        two carry "a person stopped this, never blind-retry it" (design §6) since the
        hold ladder removed the ``needs_human`` triage state (spec 2026-09-18 §3): a
        rejected proposal parks its item under an ``owner_action`` hold and leaves it
        ``unclassified``, and the legacy conversion does the same to every pre-ladder
        row. Filtering on ``triage_state`` alone would put all of them back in the
        candidate set, spend a classify session each and re-raise an inbox card for
        work a person already rejected.

        An ``evidence`` or ``stronger_model`` hold parks the WORK, not the filing: it
        says nothing about where the item belongs. And since every auto-filed error
        report is now BORN under an ``evidence`` hold (spec §5,
        ``_pm_sync_upsert_items``), excluding that kind would leave the entire
        auto-error stream permanently unclassified."""
        from sqlalchemy import or_
        from server.db.models import WorkItem
        from server.pm.desired_state import HELD_KINDS
        return or_(WorkItem.hold_kind.is_(None),
                   WorkItem.hold_kind.not_in(sorted(HELD_KINDS)))

    async def _pm_triage_list_pending(self) -> list:
        """Open, unclassified, not parked by a HELD_KINDS hold, and with NO pending
        proposal — the classify candidate set (see ``_classifiable_hold_clause``)."""
        from sqlalchemy import select
        from server.automations.pm_triage import PendingItemView
        from server.db.models import TriageProposal, WorkItem
        async with db_session() as db:
            pending_ids = set((await db.execute(
                select(TriageProposal.work_item_id)
                .where(TriageProposal.status == "pending")
            )).scalars().all())
            rows = (await db.execute(
                select(WorkItem).where(
                    WorkItem.state == "open",
                    WorkItem.triage_state == "unclassified",
                    self._classifiable_hold_clause())
            )).scalars().all()
            return [PendingItemView(
                repo=w.repo or "", number=w.number or 0, kind=w.kind or "issue",
                title=w.title or "", body=w.body or "",
                labels=tuple(w.labels or ()),
                linked_issue_numbers=tuple(w.linked_issue_numbers or ()),
            ) for w in rows if w.id not in pending_ids]

    async def _pm_triage_auto_link(self, item) -> bool:
        """Mechanical routing, no AI session (design §6.2): a PR whose closing
        refs point at a classified issue inherits that feature
        (``classified_by='auto-link'``) — the closing reference IS the evidence.
        Falls through to ``_pm_triage_route_by_label`` when that does not link,
        so a labelled issue with no closing ref still gets a mechanical home."""
        from datetime import datetime, timezone
        from sqlalchemy import select
        from server.db.models import WorkItem
        numbers = [int(n) for n in (item.linked_issue_numbers or ())]
        if not numbers:
            return await self._pm_triage_route_by_label(item)
        async with db_session() as db:
            issue = (await db.execute(
                select(WorkItem).where(
                    WorkItem.repo == item.repo,
                    WorkItem.kind == "issue",
                    WorkItem.number.in_(numbers),
                    WorkItem.feature_id.isnot(None))
            )).scalars().first()
            if issue is None:
                return await self._pm_triage_route_by_label(item)
            pr = (await db.execute(
                select(WorkItem).where(
                    WorkItem.repo == item.repo, WorkItem.kind == "pr",
                    WorkItem.number == item.number)
            )).scalar_one_or_none()
            if pr is None:
                return await self._pm_triage_route_by_label(item)
            pr.feature_id = issue.feature_id
            pr.triage_state = "classified"
            pr.classified_by = "auto-link"
            # Naive-UTC everywhere: never func.now() (Postgres CURRENT_TIMESTAMP
            # is tz-aware and SQLite-only tests hide the difference).
            pr.classified_at = datetime.now(timezone.utc)
        return True

    async def _pm_triage_label_route_cache_for(self, repo: str) -> dict[str, str | None]:
        """(folded label → feature id, or ``None`` when two features in the
        project both claim it) for *repo*'s owning project, cached for 60s.

        pm-triage ticks every 60s and offers every labelled pending item to
        ``_pm_triage_route_by_label``; without this cache each one opened a DB
        session (``owning_projects_by_repo`` + the ``Feature.route_labels``
        scan) just to answer "does this route anywhere" — most of the time,
        for a route map that rarely changes. Built with the same two queries
        the old per-item path used, once per repo per 60s."""
        import time as _time
        from sqlalchemy import select
        from server.db.models import Feature
        from server.pm.repo_project import owning_projects_by_repo
        cache = getattr(self, "_label_route_cache", None)
        if cache is None:
            cache = {}
            self._label_route_cache = cache
        now = _time.monotonic()
        cached = cache.get(repo)
        if cached is not None and now - cached[0] < 60.0:
            return cached[1]
        route_map: dict[str, str | None] = {}
        async with db_session() as db:
            owner = (await owning_projects_by_repo(db, [repo])).get(repo)
            if owner is not None:
                rows = (await db.execute(select(Feature).where(
                    Feature.project_id == owner.project_id,
                    Feature.route_labels.isnot(None),
                    Feature.orphaned.isnot(True)))).scalars().all()
                for f in rows:
                    for lbl in (f.route_labels or []):
                        folded = str(lbl).strip().lower()
                        if not folded:
                            continue
                        if folded in route_map and route_map[folded] not in (None, f.id):
                            route_map[folded] = None   # two features claim the same label
                        else:
                            route_map.setdefault(folded, f.id)
        cache[repo] = (now, route_map)
        return route_map

    async def _pm_triage_route_by_label(self, item) -> bool:
        """``labels:`` on a feature doc → mechanical home for a labelled item.
        Exactly one feature in the item's OWNING project must route one of its
        labels; zero or several → False, the classifier decides.

        GitHub labels are case-insensitive, so the comparison folds both sides
        (precedent: ``server/pm/queue.py``'s ``{lbl.strip().lower() for lbl in
        row.labels}``) — a doc's ``labels: [Flaky]`` must still route GitHub's
        ``flaky``. Only the comparison folds; ``Feature.route_labels`` keeps the
        doc's own spelling on disk.

        The route map lookup (``_pm_triage_label_route_cache_for``) opens no DB
        session once warm; a session opens only to WRITE the WorkItem once
        exactly one feature is resolved for this item's labels."""
        labels = {lbl.strip().lower() for lbl in (item.labels or ()) if lbl and lbl.strip()}
        if not labels:
            return False
        route_map = await self._pm_triage_label_route_cache_for(item.repo)
        resolved_ids: set[str] = set()
        ambiguous = False
        for lbl in labels:
            if lbl not in route_map:
                continue
            fid = route_map[lbl]
            if fid is None:
                ambiguous = True
            else:
                resolved_ids.add(fid)
        if ambiguous or len(resolved_ids) != 1:
            return False
        feature_id = next(iter(resolved_ids))
        from datetime import datetime, timezone
        from sqlalchemy import select
        from server.db.models import WorkItem
        async with db_session() as db:
            wi = (await db.execute(select(WorkItem).where(
                WorkItem.repo == item.repo, WorkItem.kind == item.kind,
                WorkItem.number == item.number))).scalar_one_or_none()
            if wi is None or wi.feature_id is not None:
                return False
            wi.feature_id = feature_id
            wi.triage_state = "classified"
            wi.classified_by = "label-route"
            wi.classified_at = datetime.now(timezone.utc)
        return True

    async def _pm_triage_open_map_diffs(self, clusters) -> tuple[str, ...]:
        """Suggestions the drift branch must NOT re-propose (``TriageState.
        open_map_diff_suggestions``).

        A ``no_fit`` cluster is permanent — accepting a proposal never clears its
        ``no_fit_suggestion`` — and the drift branch is not day-capped, so without
        this latch every tick opens another archaeology-diff PR for the same
        capability, forever. Spawn-time dedupe cannot cover it: it matches only
        NON-terminal sessions, so the tick after the map-diff session finishes
        spawns a fresh one.

        A suggestion is latched when it is
          (a) already resolved — a ``Feature`` with that slug exists **in the
              owning project** (the diff merged; the orphans now flow through the
              accept path's drift branch, not a second PR). ``Feature.slug`` is
              unique per ``(project_id, slug)`` only (``uq_feature_slug``), so an
              unscoped lookup would latch on another product's feature; or
          (b) already in flight — a non-terminal session exists for the map-diff
              spawn's ``origin_ref``/``dedupe_key`` ``<slug>:map-diff:<suggestion>``;
              or
          (c) unresolvable — the cluster's repo maps to no project, so
              ``_pm_triage_propose_map_diff`` can only skip. Latching it keeps a
              dead cluster from monopolising the branch and starving the clusters
              that CAN be proposed; or
          (d) durable dispositions are filtered out of the input clusters.
              Session rows are disposable and never evidence about new proposals.
        """
        from sqlalchemy import select
        from server.db.models import Feature, Project
        from server.pm.repo_project import owning_projects_by_repo
        latched: set[str] = set()
        slugs: dict[str, str] = {}
        async with db_session() as db:
            slugs = {repo: owner.slug for repo, owner in (
                await owning_projects_by_repo(
                    db, {c.repo for c in clusters})).items()}
            for c in clusters:
                slug = slugs.get(c.repo)
                if slug is None:
                    latched.add(c.suggestion)          # (c)
                    continue
                feat = (await db.execute(
                    select(Feature.id)
                    .join(Project, Project.id == Feature.project_id)
                    .where(Project.slug == slug,
                           Feature.slug == c.suggestion))).scalars().first()
                if feat is not None:
                    latched.add(c.suggestion)          # (a)
                    continue
        # (b) runs OUTSIDE the session above: _existing_session opens its own, and
        # it is deliberately the SAME lookup the spawn dedupes with — reusing the
        # spawning context means the origin id and the terminal-status set can
        # never drift from the spawn path.
        for c in clusters:
            slug = slugs.get(c.repo)
            if slug is None:  # pragma: no cover — already latched by (c)
                continue
            key = f"{slug}:map-diff:{c.suggestion}"
            existing = await self._pm_onboard_ctx._existing_session(key)
            if existing is not None:
                latched.add(c.suggestion)
                rec = getattr(self, "_records", {}).get(existing.id)
                if (rec is not None and rec.status == "done"
                        and self._pm_onboard_is_map_diff(rec)
                        and self._owns_record(rec, None)):
                    # A retained plain-done turn has no new status event after
                    # rollout. Reuse completion's guarded verifier; awaiting it
                    # bounds work to this serial tick and its per-session guard
                    # deduplicates an overlapping driver turn-end callback.
                    await self._certify_unmarked_map_diff_turn(
                        rec, rec.updated_at, rec.last_user_interaction_at)
        return tuple(sorted(latched))

    async def _pm_triage_count_state(self):
        """Build the pure engine view from DB counts (design §6). Excludes
        HELD_KINDS-parked and already-proposed items from ``unclassified_count`` —
        literally the same ``_classifiable_hold_clause`` ``_pm_triage_list_pending``
        applies, so the count and the list cannot disagree.

        ``day_spawns`` is reported as 0 on purpose: the DB holds no record of the
        sessions THIS process spawned in the window, and ``PmTriageLoop._budgeted``
        substitutes its own ledger (a non-zero value here would win and defeat
        the cap)."""
        from datetime import datetime, timezone
        from sqlalchemy import func, select
        from server.db.models import Feature, TriageProposal, WorkItem
        from server.pm.engine import NoFitCluster, StaleFeature, TriageState
        mode, config = await self._pm_triage_read_config()
        stale_days = int(config.get("stale_days", 14))
        now = datetime.now(timezone.utc)
        async with db_session() as db:
            pending_ids = set((await db.execute(
                select(TriageProposal.work_item_id)
                .where(TriageProposal.status == "pending")
            )).scalars().all())
            open_unclassified = (await db.execute(
                select(WorkItem.id).where(
                    WorkItem.state == "open",
                    WorkItem.triage_state == "unclassified",
                    self._classifiable_hold_clause())
            )).scalars().all()
            unclassified = sum(1 for wid in open_unclassified
                               if wid not in pending_ids)
            pending_count = len(pending_ids)
            # Drift clusters: accepted no_fit proposals grouped by
            # (suggestion, repo) — NOT by suggestion alone. A map-diff PR targets
            # exactly one repo, so merging every repo's item numbers under the
            # first repo seen would name repo A while citing repo B's issue
            # numbers, and those numbers resolve to unrelated issues in A.
            accepted_nofit = (await db.execute(
                select(TriageProposal, WorkItem)
                .join(WorkItem, WorkItem.id == TriageProposal.work_item_id)
                .where(TriageProposal.status == "accepted",
                       TriageProposal.no_fit_suggestion.isnot(None))
            )).all()
            clusters: dict[tuple[str, str], list[int]] = {}
            from server.pm.map_resolution import map_resolution_inputs
            for proposal, item in accepted_nofit:
                if (proposal.map_resolution or {}).get("inputs") == map_resolution_inputs(
                        proposal, item):
                    continue
                clusters.setdefault((proposal.no_fit_suggestion, item.repo or ""), []).append(
                    int(item.number or 0))
            no_fit_clusters = tuple(
                NoFitCluster(suggestion=s, item_numbers=tuple(sorted(nums)),
                             repo=r)
                for (s, r), nums in clusters.items())
            # Stale features: discovery/delivering with no linked work-item
            # activity in the window and an untouched index row.
            feats = (await db.execute(
                select(Feature).where(
                    Feature.state.in_(("discovery", "delivering"))))).scalars().all()
            stale: list[StaleFeature] = []
            for f in feats:
                last = (await db.execute(
                    select(func.max(WorkItem.gh_updated_at))
                    .where(WorkItem.feature_id == f.id))).scalar_one_or_none()
                marker = last or f.updated_at
                if marker is None:
                    continue
                if marker.tzinfo is None:
                    # SQLite hands back naive datetimes for DateTime(timezone=True)
                    # columns; Postgres hands back aware ones. Everything we
                    # persist is UTC, so normalize rather than crash on one
                    # dialect only.
                    marker = marker.replace(tzinfo=timezone.utc)
                days_idle = (now - marker).days
                if days_idle >= stale_days:
                    stale.append(StaleFeature(
                        slug=f.slug or "", state=f.state or "",
                        days_idle=days_idle))
        return TriageState(
            mode=mode, unclassified_count=unclassified,
            pending_count=pending_count, no_fit_clusters=no_fit_clusters,
            stale_features=tuple(stale), day_spawns=0,
            day_cap=int(config.get("max_spawns_per_day", 8)),
            open_map_diff_suggestions=await self._pm_triage_open_map_diffs(
                no_fit_clusters))

    async def _pm_triage_classify(self, items, count):
        """Spawn ONE classify session over the batch by REUSING the phase-2
        classify seam ``pm_classify_run`` (which builds the prompt via
        ``pm.classification`` and chains ``_pm_classify_ingest`` to record the
        ``TriageProposal`` rows). There is no second classifier — design §6.1.

        The batch is scoped to ONE project: ``pm_classify_run`` compares items
        against that project's feature list, so an item from another project's
        repo would be classified against the wrong map. Items outside the leading
        item's project stay pending and lead a later tick."""
        from server.pm.repo_project import owning_projects_by_repo
        batch = list(items[:count])
        if not batch:
            return None
        async with db_session() as db:
            owners = await owning_projects_by_repo(db, {i.repo for i in batch})
        owner = owners.get(batch[0].repo)
        if owner is None:
            await self._pm_triage_ctx.emit(
                "info", f"no project owns {batch[0].repo} — skipping classify",
                kind="skipped", target=batch[0].repo)
            return None
        scoped = [i for i in batch if owners.get(i.repo) == owner]
        return await self.pm_classify_run(
            owner.slug, items=[(i.repo, i.number, i.kind) for i in scoped])

    async def _pm_triage_propose_map_diff(self, suggestion, numbers, repo):
        """Open a scoped archaeology-diff PR for the unnamed capability by
        REUSING the parameterized phase-2 map seam ``pm_onboard_spawn_map`` with
        ``scope="diff"`` — there is NO second map-synthesis path (constitution
        VI). On merge, pm-sync indexes the new Feature and the accept path
        re-proposes the orphaned items.

        A repo no project owns is a skip, never a guess: the map seam is keyed by
        project slug and ``Feature.slug`` is unique only within a project, so a
        guessed project would diff another product's map."""
        from server.pm.repo_project import owning_projects_by_repo
        async with db_session() as db:
            owner = (await owning_projects_by_repo(db, {repo})).get(repo)
        if owner is None:
            await self._pm_triage_ctx.emit(
                "info",
                f"no project owns {repo} — skipping map diff for '{suggestion}'",
                kind="skipped", target=repo)
            return None
        from types import SimpleNamespace
        target = SimpleNamespace(origin=self._pm_onboard_ctx.automation_id,
                                 origin_ref=f"{owner.slug}:map-diff:{suggestion}", repo=repo)
        from sqlalchemy import select
        async with db_session() as db:
            legacy_archive = (await db.execute(select(DbSession).where(
                DbSession.origin == target.origin, DbSession.origin_ref == target.origin_ref,
                DbSession.repo == repo, DbSession.status == "archived",
                DbSession.archived_at.is_not(None), DbSession.archived_by.is_not(None),
                DbSession.archived_by.not_in(AUTO_ARCHIVE_PROVENANCE),
            ).order_by(DbSession.archived_at.desc()))).scalars().first()
        if legacy_archive is not None:
            await self._pm_onboard_observe_map_diff_not_needed(
                legacy_archive, disposition_source="human-archive")
        if await self._pm_onboard_observe_map_diff_not_needed(target):
            return None
        return await self.pm_onboard_spawn_map(
            owner.slug, scope="diff", suggestion=suggestion,
            item_numbers=tuple(numbers), repo=repo)

    async def _pm_triage_mark_stale(self, slugs) -> None:
        """Low-key staleness indicator (design §6.4). Persists NOTHING by design:
        the board derives staleness from ``Feature.updated_at`` + linked-item
        activity (the same computation as ``_pm_triage_count_state``), so there is
        no column to write and no schema change to make. This seam only emits the
        feed event."""
        if slugs:
            await self._pm_triage_ctx.emit(
                "info", f"stale features: {', '.join(slugs)}",
                kind="stale_features", detail={"slugs": list(slugs)})

    async def _pm_triage_load_policies(self) -> dict[str, dict]:
        """The triage loop's ``read_policies`` seam: slug → validated product
        policy. RAISES on failure (the loop skips the auto-accept pass for the
        tick with a warn) — ``{}`` would read as "no product opted in"."""
        from server.automations.product_policy import load_policies
        try:
            async with db_session() as db:
                return await load_policies(db)
        except Exception:
            log.warning("orchestrator._pm_triage_load_policies_failed", exc_info=True)
            raise

    async def _pm_triage_list_auto_accept_candidates(self) -> list:
        """Every pending proposal, with what the auto-accept gate needs:
        owning product (via ``owning_projects_by_repo`` — the ONE repo→project
        resolver), the target capability's lifecycle state, and the flags.

        Ordered OLDEST FIRST, and that is load-bearing: the loop accepts only
        the first ``MAX_AUTO_ACCEPTS_PER_TICK`` per product, so an unordered
        read would leave *which* of a backlog gets accepted to the storage
        engine (Postgres reorders a heap after UPDATE/VACUUM, or when the plan
        flips seq-scan↔index-scan) and a proposal could be jumped by newer ones
        tick after tick. Oldest-first is also the queue order the inbox shows.

        ``id`` breaks the tie, because ``created_at`` alone is not a total order:
        one classify session writes its whole batch in a single transaction, and
        on Postgres that is one ``CURRENT_TIMESTAMP`` for every row in it — ties
        are the common case. Which of a tied batch the per-product cap admits
        would otherwise be back to the storage engine. The id is arbitrary, but
        it is STABLE, which is the whole property the cap needs."""
        from sqlalchemy import select
        from server.automations.pm_triage import AutoAcceptCandidateView
        from server.db.models import Feature, TriageProposal, WorkItem
        from server.pm.repo_project import owning_projects_by_repo
        async with db_session() as db:
            rows = (await db.execute(
                select(TriageProposal, WorkItem)
                .join(WorkItem, WorkItem.id == TriageProposal.work_item_id)
                .where(TriageProposal.status == "pending")
                .order_by(TriageProposal.created_at, TriageProposal.id))).all()
            repos = {wi.repo for _, wi in rows if wi.repo}
            owners = await owning_projects_by_repo(db, repos) if repos else {}
            feature_ids = {p.proposed_feature_id for p, _ in rows if p.proposed_feature_id}
            states: dict[str, str | None] = {}
            if feature_ids:
                states = {fid: st for fid, st in (await db.execute(
                    select(Feature.id, Feature.state).where(
                        Feature.id.in_(feature_ids)))).all()}
            out = []
            for prop, wi in rows:
                owner = owners.get(wi.repo or "")
                out.append(AutoAcceptCandidateView(
                    proposal_id=prop.id, work_item_id=wi.id,
                    product_slug=owner.slug if owner else None,
                    repo=wi.repo or "", number=wi.number or 0,
                    confidence_level=prop.confidence_level,
                    proposed_feature_id=prop.proposed_feature_id,
                    feature_state=(states.get(prop.proposed_feature_id)
                                   if prop.proposed_feature_id else None),
                    auto_undone=prop.auto_undone))
            return out

    async def _pm_triage_auto_accept(self, proposal_id: str) -> "dict | None":
        """The loop's ``auto_accept`` seam: ONE transaction — re-read the
        proposal (a human may have resolved it since the list), accept through
        the shared ``apply_accept`` with ``decided_by="auto"``, audit
        ``pm.triage.auto_accept`` as ``pm-triage``. Returns the audit detail, or
        ``None`` when there was nothing left to accept.

        The re-read takes a row lock (the shared ``pending_proposal_stmt``,
        which explains it): this loop and a human at the inbox are two writers
        for one proposal, and unlocked they can both read "pending" under
        Postgres READ COMMITTED and both write — last committer wins, so the
        loop's plain copy can silently overwrite a human's accept-with-edits and
        stamp it ``classified_by="auto"``. Locked, the loser re-reads the row as
        ``accepted`` and returns ``None`` here."""
        from server.audit import record_audit
        from server.pm.triage_accept import (
            DECIDED_BY_AUTO, WorkItemMissing, apply_accept, pending_proposal_stmt,
            gather_accept_ownership)
        from server.pm.repo_project import OwnershipConflict
        ownership = await gather_accept_ownership([proposal_id])
        async with db_session() as db:
            prop = (await db.execute(
                pending_proposal_stmt(proposal_id))).scalar_one_or_none()
            if prop is None or prop.status != "pending":
                return None
            try:
                await apply_accept(db, prop, decided_by=DECIDED_BY_AUTO,
                                   audit_identity="pm-triage", ownership=ownership)
            except OwnershipConflict:
                return None
            except WorkItemMissing:
                # The work item row is gone (deleted/reconciled away since the
                # listing): there is nothing to classify, so this is the same
                # "nothing left to accept" answer as a human beating us to it —
                # not a failure worth a warn event on every tick.
                log.warning("orchestrator._pm_triage_auto_accept_work_item_missing: %s",
                            proposal_id)
                return None
            wi_id = prop.work_item_id
            detail = {"proposalId": prop.id, "workItemId": wi_id,
                      "featureId": prop.proposed_feature_id,
                      "confidence": prop.confidence_level}
            await record_audit(db=db, type="pm.triage.auto_accept",
                               identity="pm-triage", detail=detail)
            return {"workItemId": wi_id, "featureId": prop.proposed_feature_id,
                    "confidence": prop.confidence_level}

    async def _pm_triage_tick_loop(self, interval: float) -> None:
        """Periodic driver for the pm-triage control loop (mirrors _pm_sync_tick_loop)."""
        while True:
            await self._pm_triage_tick_once()
            await asyncio.sleep(interval)

    async def _pm_triage_tick_once(self) -> None:
        """One pm-triage tick + an enabled-only ``last_active_at`` heartbeat.
        Best-effort — neither the tick nor the heartbeat may crash the loop."""
        if not await self._schedule_allows_tick("pm-triage"):
            return
        try:
            await self._pm_triage_loop.tick()
        except Exception:  # pragma: no cover — tick() already swallows; belt+braces
            log.warning("pm_triage.tick_loop_error", exc_info=True)
        try:
            mode, _ = await self._pm_triage_read_config()
            if mode != "off":
                await self._bump_automation_active("pm-triage")
        except Exception:  # pragma: no cover — a heartbeat failure must not stall
            log.debug("pm_triage.bump_active_failed", exc_info=True)

    # ------------------------------------------------------------------
    # GitHub Reconcile control-loop dependencies (injected into GhReconcileLoop)
    #
    # Everything GitHub-facing is REUSED from the pm-sync seams above (the
    # PAT-preferring GraphQL fetch, the product list, the field-cache writer) —
    # a mutation document is just a document. Only the journal, the facts loader,
    # the sync request and the kill switch are new, and each is a thin wrapper
    # over one pure function so the loop's logic stays in the automation module.
    # ------------------------------------------------------------------

    async def _gh_reconcile_read_config(self) -> tuple[str, dict]:
        """The gh-reconcile row's (mode, config) merged onto schema defaults.

        Mirrors ``_sdlc_synth_read_config``: three modes, and anything other than
        an enabled row carrying ``dry_run``/``apply`` resolves to ``off`` — a bad
        or absent row can never write to GitHub. No ``default_mode``: an enabled row
        with no mode must NOT fall through to a mode that writes."""
        from server.automations.config_store import read_automation_config
        from server.automations.gh_reconcile import GhReconcile
        return await read_automation_config(
            GhReconcile, modes=("dry_run", "apply"),
            log_key="gh_reconcile")

    @staticmethod
    def _gh_reconcile_kill_switch() -> bool:
        """VIBERPIT_GH_RECONCILE_ENABLED, re-read from settings every cycle.

        Re-reading is not the same as picking up an edit: the value comes from the
        daemon's process environment (systemd env file), so flipping the kill switch
        off in ``/etc/ccswitch/daemon.env`` takes effect only after a daemon restart.
        To stop the reconciler without one, set the automation's mode to ``off``."""
        from server.config import get_settings
        return bool(get_settings().gh_reconcile_enabled)

    async def _gh_reconcile_load_facts(self, product, now):
        """One product's reconcile inputs (mirror, decisions, deps, node ids)."""
        from server.pm import reconcile_inputs
        async with db_session() as db:
            return await db.run_sync(
                lambda s: reconcile_inputs.load_product_facts(s, product, now=now))

    async def _gh_reconcile_request_sync(self, project_id: str) -> None:
        """Ask pm-sync for a forced pass over the product's repos.

        The reconciler uses this both BEFORE writing (a stale mirror is refused,
        not written through) and AFTER (so our own writes are re-ingested and
        echo-suppressed rather than read back as human edits). Same helper the
        sync-now API endpoint uses, so the two cannot drift."""
        from server.pm.sync_request import request_project_sync
        async with db_session() as db:
            await request_project_sync(db, project_id, self._pm_sync_now_utc())

    async def _gh_reconcile_journal_record(self, mutations: list, batch_id: str,
                                           now, dry_run: bool) -> list[str]:
        """Write-ahead: persist the batch as pending BEFORE it is sent."""
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(lambda s: journal.record_pending(
                s, mutations, batch_id=batch_id, now=now, dry_run=dry_run))

    async def _gh_reconcile_journal_applied(self, row_ids: list[str], now) -> None:
        from server.pm import journal
        async with db_session() as db:
            await db.run_sync(lambda s: journal.mark_applied(s, row_ids, now))

    async def _gh_reconcile_journal_failed(self, row_id: str, error: str, now) -> None:
        from server.pm import journal
        async with db_session() as db:
            await db.run_sync(lambda s: journal.mark_failed(s, row_id, error, now))

    async def _gh_reconcile_journal_park(self, row_id: str, reason: str, now) -> None:
        from server.pm import journal
        async with db_session() as db:
            await db.run_sync(lambda s: journal.park(s, row_id, reason, now))

    async def _gh_reconcile_journal_failure_count(self, mutation_id: str) -> int:
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(lambda s: journal.failure_count(s, mutation_id))

    async def _gh_reconcile_journal_parked(self, mutation_id: str) -> bool:
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(lambda s: journal.is_parked(s, mutation_id))

    async def _gh_reconcile_journal_applied_keys(self) -> set[str]:
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(journal.applied_keys)

    async def _gh_reconcile_journal_own_values(self) -> dict[tuple[str, str], object]:
        """The value we last APPLIED per (item node, field) — the diff engine uses it
        to tell a human edit from our own write (which stamped gh_updated_at)."""
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(journal.own_applied_values)

    async def _gh_reconcile_journal_dry_run_keys(self, since) -> set[str]:
        """Mutation keys that already carry a dry-run row newer than *since*."""
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(lambda s: journal.recent_dry_run_keys(s, since))

    async def _gh_reconcile_journal_prune_dry_run(self, older_than) -> int:
        """Drop stale dry-run rows (a preview, not an audit record)."""
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(lambda s: journal.prune_dry_run(s, older_than))

    async def _gh_reconcile_journal_prune_applied(self, older_than) -> int:
        """Drop applied Status/Score/Stage rows a later write has superseded, bounding
        the per-cycle ``own_applied_values`` scan. The current write per (item, field)
        is kept whatever its age — it is what un-sticks our own past writes."""
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(
                lambda s: journal.prune_superseded_applied(s, older_than))

    async def _gh_reconcile_journal_recover(self, older_than) -> int:
        """Mark pending rows older than *older_than* as interrupted (crash recovery)."""
        from server.pm import journal
        async with db_session() as db:
            return await db.run_sync(
                lambda s: journal.recover_interrupted(s, older_than))

    async def _gh_reconcile_tick_loop(self, interval: float) -> None:
        """Periodic driver for the gh-reconcile control loop (mirrors _pm_sync_tick_loop)."""
        while True:
            await self._gh_reconcile_tick_once()
            await asyncio.sleep(interval)

    async def _gh_reconcile_tick_once(self) -> None:
        """One reconcile tick + an enabled-only ``last_active_at`` heartbeat.
        Best-effort — neither the tick nor the heartbeat may crash the loop."""
        if not await self._schedule_allows_tick("gh-reconcile"):
            return
        try:
            await self._gh_reconcile_loop.tick()
        except Exception:  # pragma: no cover — tick() already swallows; belt+braces
            log.warning("gh_reconcile.tick_loop_error", exc_info=True)
        try:
            mode, _ = await self._gh_reconcile_read_config()
            if mode != "off":
                await self._bump_automation_active("gh-reconcile")
        except Exception:  # pragma: no cover — a heartbeat failure must not stall
            log.debug("gh_reconcile.bump_active_failed", exc_info=True)

    # ---------------------- pm onboarding seams (2026-08-31) --------------- #

    async def pm_onboard_spawn_map(
            self, slug: str, *, scope: str = "initial",
            suggestion: str | None = None,
            item_numbers: tuple[int, ...] = (),
            repo: str | None = None):
        """ONE parameterised map-synthesis spawn seam (phase 3 reuses it with
        ``scope="diff"`` — there is no separate diff-spawn method).

        ``scope="initial"`` (default): spawn ONE archaeology map-synthesis
        session for *slug*'s primary repo and move the project to
        ``map_proposed``. Deduped on ``<slug>:feature-map`` so a re-tap does not
        double-spawn.

        ``scope="diff"``: spawn a diff-scoped session whose prompt names
        ``suggestion`` + ``item_numbers``, deduped ``<slug>:map-diff:<suggestion>``,
        and does NOT touch ``onboarding_state`` (phase-3 drift path). ``repo``
        overrides the resolved primary repo when supplied.

        Returns the SessionRecord, or None when no repo / no healthy account.
        Propose-only: the spawned session opens ONE non-draft PR and NEVER arms
        auto-merge — the merge is the human curation gate."""
        from sqlalchemy import func, select
        from server.db.models import Project, ProjectRepo, WorkItem
        from server.pm.classification import build_map_synthesis_prompt
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.slug == slug))).scalar_one_or_none()
            if proj is None:
                return None
            resolved_repo = repo
            if resolved_repo is None:
                repo_row = (await db.execute(select(ProjectRepo).where(
                    ProjectRepo.project_id == proj.id,
                    ProjectRepo.is_primary.is_(True)))).scalar_one_or_none()
                if repo_row is None or not repo_row.repo:
                    return None
                resolved_repo = repo_row.repo
            open_count = (await db.execute(select(func.count(WorkItem.id)).where(
                WorkItem.repo == resolved_repo,
                WorkItem.state == "open"))).scalar_one()
            closed_count = (await db.execute(select(func.count(WorkItem.id)).where(
                WorkItem.repo == resolved_repo,
                WorkItem.state != "open"))).scalar_one()
            project_id = proj.id
            # R8b-9 / spec §9: while a map-changes PR is open, the drift
            # session commits to THAT branch, so the UI's inline capability
            # edits and the AI's proposal ride one reviewable PR.
            map_branch: str | None = None
            if scope == "diff":
                from server.pm.map_changes import open_pointer_row
                pointer = await open_pointer_row(db, proj.id)
                map_branch = (pointer.branch or None) if pointer is not None else None
        repo = resolved_repo
        if scope == "diff":
            origin_ref = f"{slug}:map-diff:{suggestion}"
            name = f"pm map-diff {slug}"
            detail: dict = {"slug": slug, "kind": "feature-map-diff",
                            "suggestion": suggestion,
                            "itemNumbers": list(item_numbers),
                            "branch": map_branch}
        else:
            origin_ref = f"{slug}:feature-map"
            name = f"pm map {slug}"
            detail = {"slug": slug, "kind": "feature-map"}
        # Engine FIRST, before any account, network or disk work — the same
        # ordering `_backlog_spawn` and (since #1265) `_sdlc_spawn_synth` use,
        # for the same two reasons: the seed prompt states a commit trailer, the
        # one engine-specific line in it, and a refusal must COST nothing rather
        # than pay for an account probe plus a full `ensure_clone` on every tap.
        plan = await self._pm_onboard_ctx.launch_plan_or_refuse(origin_ref)
        if plan is None:
            return None
        engine, config = plan
        account = await self._automation_account_for(
            self._pm_onboard_ctx, origin_ref, engine=engine)
        if account is None:
            return None
        url = f"https://github.com/{repo}.git"
        cwd = await asyncio.to_thread(
            gitrepos.ensure_clone, await self._effective_repo_root(), repo, url)
        default_branch = await self._sdlc_default_branch(repo)
        prompt = build_map_synthesis_prompt(
            slug=slug, repo=repo, default_branch=default_branch,
            open_count=int(open_count), closed_count=int(closed_count),
            scope=scope, suggestion=suggestion, item_numbers=item_numbers,
            engine=engine, branch=map_branch)
        detail["engine"] = engine.value
        choice = await self._resolve_spawn_model(
            engine, account, config,
            f"synthesise the feature map for {slug} from {repo} "
            f"({open_count} open / {closed_count} closed items)")
        detail.update(choice.detail)
        rec = await self._pm_onboard_ctx.spawn_session(
            origin_ref=origin_ref,
            dedupe_key=origin_ref,
            repo=repo, cwd=cwd, account=account, engine=engine,
            name=name, initial_prompt=prompt,
            model=choice.model, reasoning_effort=choice.reasoning_effort,
            detail=detail)
        if rec is not None and scope == "initial":
            async with db_session() as db:
                proj = (await db.execute(select(Project).where(
                    Project.id == project_id))).scalar_one_or_none()
                if proj is not None:
                    proj.onboarding_state = "map_proposed"
                    await db.commit()
            from server.pm.classification import map_branch_name
            self._spawn(
                self._pm_onboard_chain_critic(slug, repo, map_branch_name(slug)),
                name=f"pm-critic-chain-{slug}")
        return rec

    async def pm_onboard_spawn_constitution(self, slug: str):
        """Spawn the constitution-proposal session (issue #2259, item 2 of
        #2165) — a separate spawn seam from ``pm_onboard_spawn_map`` with its
        own origin, dedupe key, and account resolution, mirroring its shape.

        Deduped on ``<slug>:constitution`` so a re-tap does not double-spawn.
        Unlike the map-synthesis seam, this NEVER touches ``onboarding_state``:
        offering a constitution proposal is independent of the required
        onboarding ladder — the caller (``/propose-constitution``) gates on
        ``Project.constitution_status`` instead.

        Returns the SessionRecord, or None when no repo / no healthy account.
        Propose-only: the spawned session opens ONE non-draft PR and NEVER
        arms auto-merge — the merge is the human governance-review gate."""
        from sqlalchemy import select
        from server.db.models import Project, ProjectRepo
        from server.pm.classification import build_constitution_proposal_prompt
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.slug == slug))).scalar_one_or_none()
            if proj is None:
                return None
            repo_row = (await db.execute(select(ProjectRepo).where(
                ProjectRepo.project_id == proj.id,
                ProjectRepo.is_primary.is_(True)))).scalar_one_or_none()
            if repo_row is None or not repo_row.repo:
                return None
            repo = repo_row.repo
            constitution_status = proj.constitution_status
        origin_ref = f"{slug}:constitution"
        name = f"pm constitution {slug}"
        detail: dict = {"slug": slug, "kind": "constitution-proposal"}
        # Engine FIRST, before any account, network or disk work — see
        # `pm_onboard_spawn_map` for why.
        plan = await self._pm_onboard_constitution_ctx.launch_plan_or_refuse(origin_ref)
        if plan is None:
            return None
        engine, config = plan
        account = await self._automation_account_for(
            self._pm_onboard_constitution_ctx, origin_ref, engine=engine)
        if account is None:
            return None
        url = f"https://github.com/{repo}.git"
        cwd = await asyncio.to_thread(
            gitrepos.ensure_clone, await self._effective_repo_root(), repo, url)
        default_branch = await self._sdlc_default_branch(repo)
        prompt = build_constitution_proposal_prompt(
            slug=slug, repo=repo, default_branch=default_branch,
            constitution_status=constitution_status, engine=engine)
        detail["engine"] = engine.value
        choice = await self._resolve_spawn_model(
            engine, account, config,
            f"draft a repository constitution for {slug} from {repo}'s ADRs, "
            f"AGENTS.md, and spec-kit templates")
        detail.update(choice.detail)
        return await self._pm_onboard_constitution_ctx.spawn_session(
            origin_ref=origin_ref,
            dedupe_key=origin_ref,
            repo=repo, cwd=cwd, account=account, engine=engine,
            name=name, initial_prompt=prompt,
            model=choice.model, reasoning_effort=choice.reasoning_effort,
            detail=detail)

    async def _pm_onboard_spawn_critic(self, slug: str, repo: str,
                                       branch: str):
        """Independent completeness-critic session on the open map PR branch
        (design §3.2). Internal-only — spawned by the chain after synthesis; never
        reached by the request layer, so it stays private (no facade/RPC forward).
        Propose-only: augments the SAME PR, never opens a new one."""
        from server.pm.classification import build_coverage_critic_prompt
        origin_ref = f"{slug}:feature-map-critic"
        # Engine before the account and the clone — see `pm_onboard_spawn_map`.
        # The critic commits and pushes to the map branch, so its prompt carries
        # the same attribution trailer the synthesis prompt does.
        plan = await self._pm_onboard_ctx.launch_plan_or_refuse(origin_ref)
        if plan is None:
            return None
        engine, config = plan
        account = await self._automation_account_for(
            self._pm_onboard_ctx, origin_ref, engine=engine)
        if account is None:
            return None
        url = f"https://github.com/{repo}.git"
        cwd = await asyncio.to_thread(
            gitrepos.ensure_clone, await self._effective_repo_root(), repo, url)
        default_branch = await self._sdlc_default_branch(repo)
        prompt = build_coverage_critic_prompt(
            slug=slug, repo=repo, default_branch=default_branch, branch=branch,
            open_count=0, closed_count=0, engine=engine)
        detail: dict = {"slug": slug, "kind": "feature-map-critic",
                        "branch": branch, "engine": engine.value}
        choice = await self._resolve_spawn_model(
            engine, account, config,
            f"critique the feature-map PR on {branch} in {repo} for completeness")
        detail.update(choice.detail)
        return await self._pm_onboard_ctx.spawn_session(
            origin_ref=origin_ref, dedupe_key=origin_ref, repo=repo, cwd=cwd,
            account=account, engine=engine, name=f"pm map-critic {slug}",
            initial_prompt=prompt,
            model=choice.model, reasoning_effort=choice.reasoning_effort,
            detail=detail)

    async def _pm_onboard_chain_critic(self, slug: str, repo: str, branch: str, *,
                                       attempts: int = 30, delay: float = 30.0):
        """Wait (bounded) for the map-synthesis PR on *branch* to appear, then spawn
        ONE completeness-critic session against it (design §3.2). No webhook: polls
        the PR poller's cache. Best-effort — a timeout just skips the critic."""
        for _ in range(attempts):
            if self.pr_for(repo, branch) is not None:
                return await self._pm_onboard_spawn_critic(slug, repo, branch)
            await asyncio.sleep(delay)
        log.warning("pm_onboard.chain_critic: map PR for %s (%s) never appeared — "
                    "skipping critic", slug, branch)
        return None

    async def pm_classify_run(
            self, slug: str, *,
            items: list[tuple[str, int, str]] | None = None) -> int:
        """One classify-spawn seam (phase 3 reuses it with an injected batch).

        With ``items=None`` (default, phase-2 onboarding path) it self-selects up
        to CLASSIFY_CHUNK_SIZE open, unclassified items with no pending proposal.
        With ``items=[(repo, number, kind), ...]`` it classifies exactly that
        caller-supplied set (phase-3 loop path). Moves the project to
        ``classifying``. Returns the item count dispatched (0 if none/no account).
        Closed history is evidence, not classified (spec §5)."""
        from sqlalchemy import select, tuple_ as sa_tuple
        from server.db.models import (
            Feature, Project, ProjectRepo, TriageProposal, WorkItem)
        from server.pm.classification import (
            CLASSIFY_CHUNK_SIZE, FeatureBrief, WorkItemBrief,
            build_classification_prompt)
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.slug == slug))).scalar_one_or_none()
            if proj is None:
                return 0
            repos = (await db.execute(select(ProjectRepo.repo).where(
                ProjectRepo.project_id == proj.id))).scalars().all()
            repo_names = [r for r in repos if r]
            primary = (await db.execute(select(ProjectRepo).where(
                ProjectRepo.project_id == proj.id,
                ProjectRepo.is_primary.is_(True)))).scalar_one_or_none()
            if items is not None:
                # Phase-3 injected batch: classify exactly the caller's set.
                if not items:
                    return 0
                keys = [(r, n) for (r, n, _k) in items]
                chunk = (await db.execute(select(WorkItem).where(
                    sa_tuple(WorkItem.repo, WorkItem.number).in_(keys)
                ))).scalars().all()
                if not chunk:
                    return 0
            else:
                pending_ids = set((await db.execute(select(
                    TriageProposal.work_item_id).where(
                        TriageProposal.status == "pending"))).scalars().all())
                selected = (await db.execute(select(WorkItem).where(
                    WorkItem.repo.in_(repo_names), WorkItem.state == "open",
                    WorkItem.triage_state == "unclassified"
                ).order_by(WorkItem.gh_updated_at.desc()).limit(
                    CLASSIFY_CHUNK_SIZE * 2))).scalars().all()
                chunk = [w for w in selected
                         if w.id not in pending_ids][:CLASSIFY_CHUNK_SIZE]
                if not chunk:
                    return 0
            features = (await db.execute(select(Feature).where(
                Feature.project_id == proj.id,
                Feature.orphaned.isnot(True)))).scalars().all()
            briefs = [WorkItemBrief(
                number=w.number or 0, kind=w.kind or "issue",
                title=w.title or "", body=w.body or "",
                labels=tuple(w.labels or []), url=w.url or "") for w in chunk]
            feat_briefs = [FeatureBrief(
                slug=f.slug or "", title=f.title or "",
                summary=f.summary or "") for f in features]
            repo = (primary.repo if primary else repo_names[0]) if repo_names else ""
            project_id = proj.id
        import hashlib as _hashlib
        # The dedupe key is the chunk's identity, not the launch's: a re-tap that
        # would classify the same items collides whichever engine it resolves to.
        _chunk_key = _hashlib.sha1(
            ",".join(f"{w.repo}#{w.number}" for w in sorted(
                chunk, key=lambda w: (w.repo or "", w.number or 0))
            ).encode()).hexdigest()[:12]
        origin_ref = f"{slug}:classify:{_chunk_key}"
        # Engine before the account gate and the clone — see
        # `pm_onboard_spawn_map`. A classify session commits nothing, so its
        # prompt is engine-neutral, but the account pool is not: probing without
        # an engine hands a Codex launch an Anthropic account that
        # `sanitize_launch_for_engine` then drops, leaving the session with none.
        plan = await self._pm_classify_ctx.launch_plan_or_refuse(origin_ref)
        if plan is None:
            return 0
        engine, config = plan
        account = await self._automation_account_for(
            self._pm_classify_ctx, origin_ref, engine=engine)
        if account is None:
            return 0
        prompt = build_classification_prompt(items=briefs, features=feat_briefs)
        cwd = None
        if repo:
            url = f"https://github.com/{repo}.git"
            cwd = await asyncio.to_thread(
                gitrepos.ensure_clone, await self._effective_repo_root(), repo, url)
        detail: dict = {"slug": slug, "kind": "classify", "count": len(chunk),
                        "engine": engine.value}
        choice = await self._resolve_spawn_model(
            engine, account, config,
            f"classify {len(chunk)} backlog items in {repo or slug} against "
            f"{len(feat_briefs)} features")
        detail.update(choice.detail)
        rec = await self._pm_classify_ctx.spawn_session(
            origin_ref=origin_ref,
            dedupe_key=origin_ref,
            repo=repo or None, cwd=cwd, account=account, engine=engine,
            name=f"pm classify {slug}", initial_prompt=prompt,
            model=choice.model, reasoning_effort=choice.reasoning_effort,
            detail=detail)
        if rec is None:
            return 0
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.id == project_id))).scalar_one_or_none()
            if proj is not None and proj.onboarding_state in (
                    "map_merged", "map_proposed"):
                proj.onboarding_state = "classifying"
                await db.commit()
        # Harvest wiring (dogfood bug: sessions completed but _pm_classify_ingest
        # had no caller, so 0 proposals ever landed). Chained daemon-side like the
        # map-critic chain; tracked via _spawn so stop() can cancel it.
        self._spawn(self._pm_classify_chain_ingest(rec.id, slug),
                    name=f"pm-classify-ingest-{slug}")
        return len(chunk)

    # Statuses meaning "the turn has finished and its final message exists" —
    # includes settled-but-live states (idle/done), not just terminal ones,
    # because a one-shot session's first finished turn IS the deliverable.
    _CHAINED_SESSION_SETTLED = ("complete", "done", "idle", "ended", "archived")
    # ...and the subset after which nothing will ever run under this id again.
    _CHAINED_SESSION_TERMINAL = ("ended", "archived")

    async def _session_settle_signal(self, session_id: str) -> tuple[str, bool] | None:
        """(status, ran) straight off the shared DB row, or None if no such row.

        Deliberately NOT ``self.get_session()``: that reads host-local ``_records``
        (#1574), which is empty for a session a chain running on the primary spawned
        onto a non-primary fleet host — every poll read back None and the chain gave
        up on a session that was alive and working the whole time. The DB row is
        written by whichever host actually owns the session's driver, so it is the
        one place this read is host-independent."""
        from sqlalchemy import select as sa_select
        async with db_session() as db:
            row = (await db.execute(sa_select(
                DbSession.status, DbSession.last_turn_at).where(
                    DbSession.id == session_id))).first()
        if row is None:
            return None
        status, last_turn_at = row
        return status, last_turn_at is not None

    async def _await_session_settled(self, session_id: str, *, attempts: int = 60,
                                     interval_s: float = 30.0) -> bool:
        """Poll until *session_id* has finished a turn; False if it never does.

        The one settle-poll for every chained ingest (classify, materialize) —
        two copies would drift on the status tuple, and a chain that waits on the
        wrong set either harvests an empty transcript or never harvests at all.
        A vanished session is a definitive False: nothing will ever settle.

        "Finished a turn" is a status in the tuple above AND ``last_turn_at``
        (#1572). Status alone cannot tell the two ``idle``s apart: a session is
        CREATED at ``idle`` and stays there when its prompt never lands —
        ``send_prompt`` returns "draining" for the whole of a deploy drain — so
        the poll called it settled 13 ms after spawn and every chain harvested an
        empty transcript. ``_persist_status`` advances ``last_turn_at`` only when
        a turn hands output back (``ACTIVITY_STATUSES``), and
        ``server/sessions/status.py`` documents ``idle`` as "never ran", so it is
        the one field that separates finished from never-started. It is a DB
        column, so the answer survives the restart that ends the drain — and,
        unlike ``get_session`` (host-local ``_records``, #1574), it is also the
        one place a session spawned onto a non-primary fleet host is actually
        visible: ``_persist_status`` writes both columns to this shared row from
        whichever host owns the session's driver, so a chain running on the
        primary can settle-poll a session it never held in memory."""
        for _ in range(attempts):
            signal = await self._session_settle_signal(session_id)
            if signal is None:
                log.warning("chain_ingest: session %s vanished — giving up", session_id)
                return False
            status, ran = signal
            if status in self._CHAINED_SESSION_SETTLED and ran:
                return True
            if status in self._CHAINED_SESSION_TERMINAL and not ran:
                # Definitive: no turn ever ran and none ever will, so spending the
                # rest of the budget (30 min classify / 2 h materialize) only
                # delays the same answer.
                log.info("chain_ingest: session %s is %s with no finished turn — "
                         "nothing to harvest", session_id, status)
                return False
            await asyncio.sleep(interval_s)
        log.warning("chain_ingest: session %s never settled after %d attempts",
                    session_id, attempts)
        return False

    async def _chained_session_output_text(self, session_id: str) -> str:
        """Full text of the session's final assistant turn(s), UNTRUNCATED.

        A chained ingest's deliverable is a ```json fenced block that can be many
        KB — the autopilot tail helper truncates per-entry, so this is a separate,
        lossless extractor. Best-effort: any failure returns ""."""
        from server.sessions.events import TextDelta
        try:
            window = await self.transcript_window(session_id, limit=2)
        except Exception:
            log.warning("chain_ingest.output_text failed sid=%s", session_id,
                        exc_info=True)
            return ""
        if window is None:
            return ""
        return "".join(e.text for e in window.events
                       if isinstance(e, TextDelta) and e.text)

    async def _pm_classify_chain_ingest(self, session_id: str, slug: str, *,
                                        attempts: int = 60,
                                        delay: float = 30.0) -> int:
        """Wait (bounded) for a classify session to settle, then harvest its JSON
        output into TriageProposal rows via ``_pm_classify_ingest`` — exactly once.

        Internal-only (chained by ``pm_classify_run``; never request-reachable, so
        no facade/RPC forward). A vanished session or timeout just gives up — the
        classify can be re-dispatched, and ingest is idempotent on re-runs."""
        if not await self._await_session_settled(session_id, attempts=attempts,
                                                 interval_s=delay):
            return 0
        text = await self._chained_session_output_text(session_id)
        written = await self._pm_classify_ingest(session_id, slug, text)
        log.info("pm_classify.chain_ingest: session=%s slug=%s wrote=%d",
                 session_id, slug, written)
        # Proposals landed → the objective is met, so say so. Only on written > 0: a
        # parse failure or an output matching no work item is precisely the run a
        # human should see, and leaving it at `done` (which lifts it into Active) is
        # how they find it. See _certify_harvested_complete.
        if written:
            await self._certify_harvested_complete(session_id)
        return written

    async def _certify_harvested_complete(self, session_id: str) -> None:
        """Drive a harvested one-shot session to ``complete``, certified by the HARNESS.

        A classify session's prompt ends "Return ONLY a JSON array", so it emits the
        fenced block and ends its turn without calling ``mark_complete`` or
        ``mark_no_pr`` — nothing in that prompt asks it to, and "ONLY" reads as
        forbidding it. ``derive_status`` then returns ``done``, which is tier
        ``your-turn``, and ``QUIET_TIERS`` (``web/src/session/backgroundSessions.ts``)
        lifts the maintenance session out of Background into Active as a stall. It had
        not stalled; it had finished, with no vocabulary to say so.

        Fixing that in the PROMPT does not work, and makes it worse. The effective goal
        of these sessions is their name, ``f"pm classify {slug}"`` — ``"classify"`` is
        not in ``completion_bar._RESEARCH_RE``, so with a repo attached the bar reads it
        as CODE work and a plain ``mark_complete`` earns "open a PR and arm auto-merge
        before finishing" at a session that exists to print JSON. ``mark_no_pr`` is no
        better: source ``tool`` is in ``SELF_CERTIFIED_SOURCES``, so it lands on the
        unverified-self-claim branch. Both make the model's own word the verification.

        The harvest is not the model's word. Proposal rows written from its output are
        the harness observing the deliverable, so the resolution is latched under
        ``HARVEST_RESOLUTION_SOURCE`` and ``met_bar`` trusts it — same shape as the
        ``queue-drain`` and ``classifier`` latches elsewhere in this file.

        The chain calling this runs on the PRIMARY, but the session it harvested was
        placed by the edge on whichever fleet host ranked best (#1574 again, one step
        after the settle-poll fix in #2234): the primary's ``_records`` never held it,
        so a host-local read here no-oped silently — 29 proposals written, session
        still ``done`` → "Your turn" → escalated to a human (prod 2026-09-23,
        fridgesheet on rocky). A record we do not hold is forwarded through the
        co-located edge, whose ``FleetOrchestrator`` routes ``certify_harvested_complete``
        by the row's host stamp to the daemon that owns the driver.
        """
        if session_id in self._records:
            await self.certify_harvested_complete(session_id)
            return
        from sqlalchemy import select as sa_select
        async with db_session() as db:
            row = (await db.execute(sa_select(DbSession.status, DbSession.host).where(
                DbSession.id == session_id))).first()
        if row is None or row[0] in ("ended", "archived"):
            # Same no-resurrection rule as the local path, decided off the shared row.
            return
        from server.config import get_settings
        from server.sessions.internal_dispatch import (
            EdgeUnreachable, certify_harvested_via_edge)
        try:
            await certify_harvested_via_edge(port=get_settings().port,
                                             session_id=session_id)
        except EdgeUnreachable as exc:
            # Fire-and-forget chain: the proposals are already durable and the
            # classify can be re-dispatched, so say so and stop rather than raise.
            log.warning("pm_classify.certify_forward_failed sid=%s host=%s: %s",
                        session_id, row[1], exc)

    async def certify_harvested_complete(self, session_id: str) -> None:
        """Certify *session_id* ``complete`` HERE, where its record and driver live.

        The RPC/facade entry for ``_certify_harvested_complete``'s forward. A host
        that does not actually hold the record (stale host stamp, torn down since)
        answers quietly: forwarding again from here would ping-pong."""
        from server.automations.completion_bar import HARVEST_RESOLUTION_SOURCE
        rec = self._records.get(session_id)
        if rec is None:
            log.info("pm_classify.certify_no_local_record sid=%s host=%s",
                     session_id, self_host_name())
            return
        if rec.status in ("ended", "archived"):
            # Ended or archived out from under the poll (the chain waits minutes).
            # A late harvest must never resurrect a session the user put away.
            return
        # Never clobber a resolution decided elsewhere — the same no-clobber rule
        # _persist_status applies to the driver's token.
        if getattr(rec, "pr_resolution", None) is None:
            await self._latch_pr_resolution(rec, "not-needed", HARVEST_RESOLUTION_SOURCE)
        # A session that already reached `complete` on its own has been judged by the
        # completion guard already (it fires from _persist_status, which ran before this
        # chain's poll noticed). Re-persisting would only re-run that judgement. The
        # latch above still lands, so the retro archive_audit pass reads the verified
        # resolution rather than the session's self-claim.
        if rec.status != "complete":
            await self._persist_status(session_id, "complete")
        log.info("pm_classify.certified_complete sid=%s", session_id)

    async def _latch_pr_resolution(self, rec, resolution: str, source: str) -> None:
        """Write a HARNESS-verified ``pr_resolution`` onto *rec* and its row.

        THE persist for a verified resolution (``harvest``, ``observed``): one shape,
        so the in-memory record and the DB row can never disagree about provenance.
        A persist failure is logged and swallowed — the caller's judgement already
        happened; the row is the audit trail, not the gate."""
        rec.pr_resolution = resolution
        rec.pr_resolution_source = source
        try:
            from sqlalchemy import update as sa_update
            async with db_session() as db:
                await db.execute(sa_update(DbSession).where(
                    DbSession.id == rec.id).values(
                        pr_resolution=resolution, pr_resolution_source=source))
        except Exception:  # noqa: BLE001 - a persist failure must not stall the caller
            log.warning("completion.resolution_persist_failed sid=%s source=%s",
                        rec.id, source, exc_info=True)

    @staticmethod
    def _pm_onboard_is_map_diff(rec) -> bool:
        return (getattr(rec, "origin", None) == "pm-onboard"
                and bool(getattr(rec, "repo", None))
                and ":map-diff:" in str(getattr(rec, "origin_ref", None) or ""))

    async def _pm_onboard_observe_map_diff_not_needed(
            self, rec, *, disposition_source: str | None = None) -> bool:
        """Persist a disposition on the evaluated proposals before session cleanup.

        Repository evidence must cover EVERY driving item (or the requested doc
        itself must exist). A majority cannot permanently dispose of minority work.
        Explicit human archive and harness classifier completion are separate
        dispositions; the latter is restricted to work predating dispatch.
        Snapshot/recheck brackets the slow git read; new or edited work is never
        silently swept into an older decision.
        """
        ref = str(getattr(rec, "origin_ref", None) or "")
        repo = str(getattr(rec, "repo", None) or "")
        if not self._pm_onboard_is_map_diff(rec):
            return False
        suggestion = ref.split(":map-diff:", 1)[1].strip()
        if not suggestion:
            return False
        from datetime import datetime, timezone
        from sqlalchemy import select
        from server.db.models import TriageProposal, WorkItem
        from server.pm.map_resolution import map_resolution_inputs
        from server.pm.repo_project import owning_projects_by_repo
        stmt = (select(TriageProposal, WorkItem)
                .join(WorkItem, WorkItem.id == TriageProposal.work_item_id)
                .where(WorkItem.repo == repo, TriageProposal.status == "accepted",
                       TriageProposal.proposed_feature_id.is_(None),
                       TriageProposal.no_fit_suggestion == suggestion))
        # A retained legacy human archive can disposition only work that existed
        # unchanged when the operator archived it. New proposals remain eligible.
        cutoff = getattr(rec, "archived_at", None) if disposition_source else None
        if disposition_source == "classifier":
            # Never promote a self-claim, and never apply the classifier's
            # judgement to proposals or issue edits arriving after dispatch.
            cutoff = getattr(rec, "created_at", None)
            if (cutoff is None or getattr(rec, "pr_resolution", None) != "not-needed"
                    or getattr(rec, "pr_resolution_source", None) != "classifier"):
                return False
        if cutoff is not None:
            from sqlalchemy import or_
            stmt = stmt.where(
                TriageProposal.created_at <= cutoff,
                or_(TriageProposal.resolved_at.is_(None), TriageProposal.resolved_at <= cutoff),
                or_(WorkItem.gh_updated_at.is_(None), WorkItem.gh_updated_at <= cutoff))
        async with db_session() as db:
            owner = (await owning_projects_by_repo(db, {repo})).get(repo)
            if owner is None or ref != f"{owner.slug}:map-diff:{suggestion}":
                return False
            rows = (await db.execute(stmt)).all()
            inputs = {p.id: map_resolution_inputs(p, w) for p, w in rows
                      if (p.map_resolution or {}).get("inputs") != map_resolution_inputs(p, w)}
        if not inputs:
            return bool(rows)
        if disposition_source is None and any(
                p.id in inputs and p.map_resolution for p, _ in rows):
            # The same issue number (or existing doc filename) says nothing
            # about newly requested scope. Leave changed work to a real agent
            # and normal PR completion or an explicit new human disposition.
            # Even an unrelated repository/doc edit must not lift this guard.
            return False
        evidence: dict = {"source": disposition_source or "observed",
                          "sessionId": getattr(rec, "id", None),
                          "observedAt": datetime.now(timezone.utc).isoformat()}
        if disposition_source is None:
            default_branch = await self._sdlc_default_branch(repo)
            clone = str(gitrepos.clone_path(await self._effective_repo_root(), repo))
            observed = await asyncio.to_thread(
                self._pm_onboard_feature_doc_citations, clone,
                f"refs/remotes/origin/{default_branch}", suggestion, repo)
            if observed is None:
                return False
            doc_exists, cited, sha, paths = observed
            numbers = {i["number"] for i in inputs.values()}
            if not doc_exists and not numbers.issubset(cited):
                return False
            evidence.update({"commit": sha, "documents": paths,
                             "suggestedDocExists": doc_exists,
                             "citedNumbers": sorted(numbers & cited)})
        async with db_session() as db:
            current = (await db.execute(stmt.with_for_update())).all()
            # If work changed during observation, leave it eligible and do not
            # declare the whole session complete. Unchanged rows can still settle.
            covered = bool(current)
            for proposal, item in current:
                snapshot = map_resolution_inputs(proposal, item)
                if (proposal.map_resolution or {}).get("inputs") == snapshot:
                    continue
                if inputs.get(proposal.id) != snapshot:
                    covered = False
                    continue
                proposal.map_resolution = {**evidence, "inputs": snapshot}
        log.info("pm_onboard.map_diff_disposition sid=%s suggestion=%s source=%s "
                 "evaluated=%d covered=%s", getattr(rec, "id", None), suggestion,
                 evidence["source"], len(inputs), covered)
        return covered

    @staticmethod
    def _pm_onboard_feature_doc_citations(
            clone: str, ref: str, suggestion: str, repo: str = "",
    ) -> tuple[bool, set[int], str, list[str]] | None:
        """Read doc existence, citations, commit and paths from a fresh default ref.

        Failed fetches are unobserved: stale cache is not durable evidence. Sync;
        call off-loop.
        """
        import re
        from server.pm.classification import FEATURE_DOCS_DIR
        try:
            fetched = subprocess.run(["git", "-C", clone, "fetch", "origin", "--quiet"],
                                     check=False, capture_output=True, timeout=120)
            if fetched.returncode != 0:
                return None
            rp = subprocess.run(
                ["git", "-C", clone, "rev-parse", "--verify", f"{ref}^{{commit}}"],
                capture_output=True, text=True, timeout=30, check=False)
            if rp.returncode != 0:
                return None
            sha = rp.stdout.strip()
            ls = subprocess.run(
                ["git", "-C", clone, "ls-tree", "-r", "--name-only", sha,
                 f"{FEATURE_DOCS_DIR}/"],
                capture_output=True, text=True, timeout=30, check=False)
            if ls.returncode != 0:
                return None
            paths = [p for p in ls.stdout.splitlines() if p.endswith(".md")]
            doc_exists = f"{FEATURE_DOCS_DIR}/{suggestion}.md" in paths
            cited: set[int] = set()
            if paths:
                gr = subprocess.run(
                    ["git", "-C", clone, "grep", "-h", "-E", r"#[0-9]+", sha,
                     "--", f"{FEATURE_DOCS_DIR}/"],
                    capture_output=True, text=True, timeout=30, check=False)
                if gr.returncode not in (0, 1):   # 1 = no matches, not an error
                    return None
                from urllib.parse import urlsplit
                from server.pm.refs import split_ref

                def link_target(match: re.Match[str]) -> str:
                    # A link label is presentation, not an issue identity.
                    # Attribute explicit links to their destination repository.
                    url = urlsplit(match.group(1).strip("<>"))
                    parts = url.path.strip("/").split("/")
                    if (url.hostname == "github.com" and len(parts) == 4
                            and parts[2] in ("issues", "pull")):
                        parsed = split_ref(f"{parts[0]}/{parts[1]}#{parts[3]}")
                        if parsed and parsed[0].casefold() == repo.casefold():
                            cited.add(parsed[1])
                    return " "

                text = re.sub(r"\[[^\]\n]*\]\(\s*([^\s)]+)[^)]*\)",
                              link_target, gr.stdout)
                # Reference-style labels have no trustworthy local identity
                # without resolving their definition. Conservatively ignore them.
                text = re.sub(r"\[[^\]\n]*\]\s*\[[^\]\n]*\]", " ", text)
                text = re.sub(r"https?://\S+", " ", text)
                for qualified in re.findall(r"[\w.-]+/[\w.-]+#[0-9]+\b", text):
                    parsed = split_ref(qualified)
                    if parsed and parsed[0].casefold() == repo.casefold():
                        cited.add(parsed[1])
                text = re.sub(r"[\w.-]+/[\w.-]+#[0-9]+\b", " ", text)
                # Unresolved/shortcut link labels must not become bare citations.
                text = re.sub(r"\[[^\]\n]*\]", " ", text)
                cited.update(int(n) for n in re.findall(
                    r"(?<![\w/])#([0-9]+)\b", text))
            return doc_exists, cited, sha, paths
        except Exception:  # noqa: BLE001 - unreadable is "unobserved", never a crash
            log.debug("pm_onboard.map_diff_observe_read_failed clone=%s ref=%s",
                      clone, ref, exc_info=True)
            return None

    async def _pm_classify_ingest(
            self, session_id: str, project_slug: str, output_text: str) -> int:
        """Turn a classify session's output into TriageProposal rows. Resolves
        each feature_slug to a Feature.id within the project; skips a row whose
        work item is missing or already has a pending proposal (idempotent
        re-ingest). Returns rows written.

        For each written row, sets ``WorkItem.triage_state = "proposed"`` as a
        scheduling marker (mirrors the fact that a proposal now exists). NEVER
        touches the SCORE overlay columns (``feature_id``, ``reach``, ``impact``,
        ``effort``, ``confidence``, ``classified_by``, ``classified_at``) — those
        are written only when a human accepts the proposal."""
        from sqlalchemy import select
        from server.db.models import (
            Feature, Project, ProjectRepo, TriageProposal, WorkItem)
        from server.pm.classification import (
            ClassificationParseError, parse_classification_output)
        if not (output_text or "").strip():
            # Nothing to read is not a parse failure (#1572). ``parse_failed``
            # carries a traceback and means "the session answered something the
            # parser could not understand" — a quality signal worth a human.
            # Raising it over absent text blamed the parser for having nothing to
            # read. The settle poll no longer hands over a session that never ran,
            # so reaching here means the transcript read itself came back empty —
            # already logged by ``_chained_session_output_text``.
            log.info("pm_classify.no_output session=%s — empty harvest, "
                     "nothing to ingest", session_id)
            return 0
        try:
            rows = parse_classification_output(output_text)
        except ClassificationParseError:
            log.warning("pm_classify.parse_failed session=%s", session_id,
                        exc_info=True)
            return 0
        written = 0
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.slug == project_slug))).scalar_one_or_none()
            if proj is None:
                return 0
            repo_names = [r for r in (await db.execute(select(
                ProjectRepo.repo).where(
                    ProjectRepo.project_id == proj.id))).scalars().all() if r]
            feat_by_slug = {f.slug: f.id for f in (await db.execute(select(
                Feature).where(Feature.project_id == proj.id))).scalars().all()}
            for row in rows:
                wi = (await db.execute(select(WorkItem).where(
                    WorkItem.repo.in_(repo_names),
                    WorkItem.number == row.number,
                    WorkItem.kind == row.kind))).scalar_one_or_none()
                if wi is None:
                    continue
                dup = (await db.execute(select(TriageProposal.id).where(
                    TriageProposal.work_item_id == wi.id,
                    TriageProposal.status == "pending"))).scalar_one_or_none()
                if dup is not None:
                    continue
                db.add(TriageProposal(
                    work_item_id=wi.id,
                    proposed_feature_id=feat_by_slug.get(row.feature_slug)
                    if row.feature_slug else None,
                    no_fit_suggestion=row.no_fit_suggestion,
                    reach=row.reach, impact=row.impact, effort=row.effort,
                    confidence=row.confidence, rationale=row.rationale,
                    confidence_level=row.confidence_level,
                    status="pending", session_id=session_id))
                wi.triage_state = "proposed"
                written += 1
            if written:
                await db.commit()
        return written

    async def pm_onboarding_counts(self, project_id: str) -> ProjectOnboardingView:
        """Build the onboarding engine's view for a project in one grouped read
        (used by the API's wizard-state endpoint)."""
        from sqlalchemy import func, select
        from server.db.models import (
            Feature, Project, ProjectRepo, TriageProposal, WorkItem)
        from server.pm.onboarding import ProjectOnboardingView
        async with db_session() as db:
            repos = (await db.execute(select(ProjectRepo).where(
                ProjectRepo.project_id == project_id))).scalars().all()
            repo_names = [r.repo for r in repos if r.repo]
            feature_count = (await db.execute(select(func.count(Feature.id)).where(
                Feature.project_id == project_id,
                Feature.orphaned.isnot(True)))).scalar_one()
            open_unclassified = 0
            pending = 0
            if repo_names:
                open_unclassified = (await db.execute(select(
                    func.count(WorkItem.id)).where(
                        WorkItem.repo.in_(repo_names), WorkItem.state == "open",
                        WorkItem.triage_state == "unclassified"))).scalar_one()
                pending = (await db.execute(select(func.count(
                    TriageProposal.id)).join(
                    WorkItem, WorkItem.id == TriageProposal.work_item_id).where(
                        WorkItem.repo.in_(repo_names),
                        TriageProposal.status == "pending"))).scalar_one()
            proj = (await db.execute(select(Project).where(
                Project.id == project_id))).scalar_one()
        return ProjectOnboardingView(
            state=proj.onboarding_state or "registered",
            repo_count=len(repos),
            backfill_done_count=sum(1 for r in repos if r.backfill_done),
            feature_count=int(feature_count),
            open_unclassified_count=int(open_unclassified),
            pending_proposal_count=int(pending))

    async def pm_advance_map_merged(self, slug: str) -> None:
        """Advance a project from ``map_proposed`` to ``map_merged`` after the
        human merges the archaeology map PR. The wizard calls this endpoint once
        the user confirms the merge; pm-sync will index the merged docs on its
        next tick and the classify step becomes available."""
        from sqlalchemy import select
        from server.db.models import Project
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.slug == slug))).scalar_one_or_none()
            if proj is not None and proj.onboarding_state == "map_proposed":
                proj.onboarding_state = "map_merged"
                await db.commit()

    async def pm_advance_live(self, slug: str) -> None:
        """Advance a project from ``map_merged``/``classifying`` to ``live`` once
        the human has drained the triage queue. The wizard's tap calls this; the
        pm-triage loop keeps classifying new items in the live loop regardless."""
        from sqlalchemy import select
        from server.db.models import Project
        async with db_session() as db:
            proj = (await db.execute(select(Project).where(
                Project.slug == slug))).scalar_one_or_none()
            if proj is not None and proj.onboarding_state in ("map_merged", "classifying"):
                proj.onboarding_state = "live"
                await db.commit()

    def pm_map_changes(self) -> "MapChangesService":
        """The capability map-changes service (roadmap spec §9), wired to this
        orchestrator's injectable ``gh`` runner, token provider and environment
        plus its default-branch probe and pm-sync seams — so the API routes
        never construct a GitHub client themselves and a test that swaps
        ``orch._gh_run``/``orch._pm_sync_read_feature_docs`` for a recorder is
        genuinely offline, credentials included."""
        from server.pm.feature_sync_seams import apply_feature_plan, list_feature_rows
        from server.pm.map_changes import MapChangesService
        from server.pm.map_changes_gh import GhWrite
        return MapChangesService(
            gh_factory=lambda repo: GhWrite(
                repo, run=self._gh_run, app_token=self._gh_token_provider,
                env=self._gh_env),
            default_branch=self._sdlc_default_branch,
            # Doc READING stays the bound method: only this process has the
            # local clone that version needs, and tests swap the attribute.
            read_feature_docs=self._pm_sync_read_feature_docs,
            # The two pure-DB seams go straight to the shared module functions
            # `RemoteOrchestrator` also uses — the bound methods are now only
            # thin wrappers around these, so this is the same behaviour with
            # one fewer hop.
            list_feature_rows=list_feature_rows,
            apply_feature_plan=apply_feature_plan,
        )

    # ------------------------------------------------------------------
    # SDLC Synthesizer control-loop dependencies (injected into SdlcSynthesizerLoop)
    # ------------------------------------------------------------------

    async def _sdlc_synth_read_config(self) -> tuple[str, dict]:
        """Loop seam → ``sdlc_synthesizer.read_synth_mode`` (the ONE reader)."""
        from server.automations.sdlc_synthesizer import read_synth_mode
        return await read_synth_mode()

    async def _sdlc_synth_fold_stored_mode(self) -> None:
        """One-shot: rewrite a stored legacy `propose`/`auto` to `on` so the row
        stops being load-bearing on the read-path fold and the API's mode select
        shows a value inside `modes`. Idempotent; `off` untouched.

        Compare-and-set, not read-modify-write: the `mode IN (legacy)` predicate is
        part of the UPDATE, so an operator PATCHing the row to an explicit `off`
        inside the window cannot be clobbered back to `on` (the spec prescribes the
        same shape for the sibling advance seam, §15)."""
        if getattr(self, "_sdlc_synth_mode_folded", False):
            return
        self._sdlc_synth_mode_folded = True
        from sqlalchemy import update as sa_update
        from server.automations.sdlc_synthesizer import LEGACY_SYNTH_MODES
        from server.db.models import Automation as AutomationRow
        try:
            async with db_session() as db:
                await db.execute(sa_update(AutomationRow).where(
                    AutomationRow.id == "sdlc-synthesizer",
                    AutomationRow.mode.in_(LEGACY_SYNTH_MODES)).values(mode="on"))
                await db.commit()
        except Exception:
            self._sdlc_synth_mode_folded = False   # retry next tick
            log.warning("sdlc_synthesizer.mode_fold_failed", exc_info=True)

    async def _sdlc_read_policies(self) -> dict[str, dict]:
        """Loop seam: slug → effective product policy (the ONE reading,
        `server/automations/product_policy.py:load_policies`)."""
        from server.automations.product_policy import load_policies
        async with db_session() as db:
            return await load_policies(db)

    async def _sdlc_live_artifact_sessions(self, session_ids: Sequence[str]) -> set[str]:
        """Loop seam: which of *session_ids* are live right now (spec 2026-09-14 §6:
        a front-chain slot is a LIVE artifact session, never a dead one or a PR
        waiting on a human). Reads the in-memory records through the same
        `ACTIVE_SESSION_STATUSES` vocabulary the PM tree uses; a session this daemon
        does not hold is not live."""
        from server.pm.desired_state import ACTIVE_SESSION_STATUSES
        out: set[str] = set()
        for sid in session_ids:
            rec = self._records.get(sid)
            if rec is not None and rec.status in ACTIVE_SESSION_STATUSES:
                out.add(sid)
        return out

    async def _sdlc_list_initiatives(self) -> list[dict]:
        """Every non-done LEAF Initiative as a plain dict (the loop's seam shape).

        An initiative is 'done' when EITHER its status or its stage is ``done`` —
        both terminal signals drop it from the loop's candidate pool. A program
        (an initiative with phases) is never driven directly — its stage/status
        are derived from its phases, so the synthesizer must never propose
        artifacts for it or materialize it as a plan. The parent-id query is
        unfiltered by status: a program with only done phases still has phases,
        and must still be excluded even though none of them appear in ``rows``.

        Rows arrive sorted by priority desc (unscored last), then age, and carry
        `project_slug`, `priority`, `epic_total`, `epic_done` (spec 2026-09-14
        D6/D7)."""
        from sqlalchemy import select
        from server.api.sdlc import _epic_progress_batch
        from server.db.models import Initiative, Project
        async with db_session() as db:
            rows = (await db.execute(select(Initiative).where(
                Initiative.status != "done", Initiative.stage != "done"))).scalars().all()
            parent_ids = set((await db.execute(select(Initiative.parent_initiative_id).where(
                Initiative.parent_initiative_id.isnot(None)))).scalars().all())
            leaves = [r for r in rows if r.id not in parent_ids]
            project_ids = {r.project_id for r in leaves if r.project_id}
            slug_by_project = {p.id: p.slug for p in (await db.execute(
                select(Project).where(Project.id.in_(project_ids)))).scalars().all()} if project_ids else {}
            progress = await _epic_progress_batch(db, leaves, include_children=False)
        out: list[dict[str, Any]] = []
        for r in leaves:
            entry = progress.get(r.id) or {}
            out.append({"id": r.id, "slug": r.slug, "repo": r.repo, "title": r.title,
                        "stage": r.stage, "status": r.status, "origin": r.origin,
                        "origin_ref": r.origin_ref,
                        # The engine decides plan-stage materialization off this pointer
                        # (spec 003 §7b) — without it every merged plan looks un-decomposed.
                        "epic_repo": r.epic_repo, "epic_number": r.epic_number,
                        # Spec 2026-09-14 D7: the loop caps per product and the engine's
                        # build gate reads the epic's completion.
                        "project_slug": slug_by_project.get(r.project_id) if r.project_id else None,
                        "priority": entry.get("priority"),
                        "epic_total": int(entry.get("total") or 0),
                        "epic_done": int(entry.get("done") or 0),
                        "_created_at": r.created_at})
        # Highest priority first, unscored last, oldest first on ties (D6/D7).
        out.sort(key=lambda d: (d["priority"] is None, -(d["priority"] or 0.0), d["_created_at"]))
        for d in out:
            d.pop("_created_at", None)
        return out

    async def _sdlc_list_artifacts(self, initiative_id: str) -> list[dict]:
        """Every InitiativeArtifact index row for *initiative_id* as a plain dict."""
        from sqlalchemy import select
        from server.db.models import InitiativeArtifact
        async with db_session() as db:
            rows = (await db.execute(select(InitiativeArtifact).where(
                InitiativeArtifact.initiative_id == initiative_id))).scalars().all()
        return [{"id": r.id, "kind": r.kind, "pr_number": r.pr_number,
                 "pr_url": r.pr_url, "commit_sha": r.commit_sha,
                 "session_id": r.session_id,
                 "auto_merge_armed_at": r.auto_merge_armed_at} for r in rows]

    async def _sdlc_record_artifact(self, *, initiative_id: str, kind: str,
                                    repo_path: str, session_id: str | None,
                                    model: str | None,
                                    upstream_ref: str | None = None) -> None:
        """Insert an InitiativeArtifact index row for a freshly-spawned session.

        ``upstream_ref`` records what actually seeded the prompt when it was
        not the normal committed file — e.g. ``"owner/repo#42"`` for an
        epic-adoption spec stage (#2159) — so the initiative page can show
        where the spec came from."""
        from server.db.models import InitiativeArtifact
        async with db_session() as db:
            db.add(InitiativeArtifact(
                initiative_id=initiative_id, kind=kind, repo_path=repo_path,
                session_id=session_id, model=model, upstream_ref=upstream_ref))
            await db.commit()

    async def _sdlc_set_status(self, initiative_id: str, status: str) -> None:
        """Update an Initiative's status (e.g. → ``awaiting_human`` post-spawn)."""
        from sqlalchemy import update
        from server.db.models import Initiative
        async with db_session() as db:
            await db.execute(update(Initiative).where(
                Initiative.id == initiative_id).values(status=status))
            await db.commit()

    async def _sdlc_advance_stage(self, initiative_id: str, from_stage: str,
                                  to_stage: str, gate: dict) -> bool:
        """The synthesizer's ``Advance`` write (spec 2026-09-14 §6/§8/§15): move
        the initiative ``from_stage → to_stage``, activate it, and record what
        the machine did in ``last_auto_gate`` — in ONE compare-and-set UPDATE.

        The ``WHERE stage = from_stage AND status != 'blocked'`` predicate is the
        race rule from §15: a human's newer Step back (or block) between the
        engine's decision and this write wins, the UPDATE touches nothing and
        the caller sees ``False`` ("stale"). Same shape the human route
        (``POST /initiatives/{slug}/advance``) writes, plus the record; the
        audit row is the machine's counterpart of that route's
        ``sdlc.initiative.advance`` entry."""
        from sqlalchemy import update
        from server.audit import record_audit
        from server.db.models import Initiative
        async with db_session() as db:
            result = await db.execute(
                update(Initiative)
                .where(Initiative.id == initiative_id,
                       Initiative.stage == from_stage,
                       Initiative.status != "blocked")
                .values(stage=to_stage, status="active", last_auto_gate=gate))
            # `CursorResult.rowcount` — typed away on the async Result wrapper.
            advanced = int(getattr(result, "rowcount", 0) or 0) == 1
            if advanced:
                await record_audit(
                    db=db, type="sdlc.gate.auto_resolve", identity="sdlc-synthesizer",
                    detail={"initiativeId": initiative_id, "gate": gate.get("gate"),
                            "tolerance": gate.get("tolerance"),
                            "from": from_stage, "to": to_stage})
            await db.commit()
        return advanced

    async def _sdlc_arm_auto_merge(self, artifact_id: str, repo: str, pr_number: int,
                                   initiative_id: str, gate: dict) -> dict:
        """The synthesizer's ``MergeArtifact`` write (spec 2026-09-14 §6/§8): arm
        GitHub auto-merge (squash) on the stage artifact PR, then stamp
        ``auto_merge_armed_at`` so no later tick spends a second ``gh`` call on
        the same PR.

        Reuses ``ready_merge`` — the ONE ``gh pr merge --squash --auto`` writer
        in this codebase (the Plotroom PrRow action) — rather than a second copy.
        GitHub applies the repo's branch protection, so "auto" stays bounded by
        CI; there is deliberately no ``--merge`` fallback.

        ``gate`` is the ``auto_gate_record`` the caller (``_arm``) already built
        (same helper ``_advance`` uses, so every reader — ``gates.py:_summary``,
        the roadmap ``autoResolved`` chip — agrees on the shape). The caller
        cannot know gh's outcome yet, so it defaults ``outcome="resolved"``; this
        method corrects it to ``"refused"`` before persisting when gh declines.
        Spec §8 requires ``last_auto_gate`` recorded on EITHER outcome — a
        refusal stamps the record but never ``auto_merge_armed_at``, so the
        artifact stays at ``AwaitApproval``. The caller (``_arm`` in
        ``sdlc_synthesizer.py``) is what stops a refusal from being retried —
        and its ``gate_refused`` feed event from repeating — every tick
        forever; this method itself never re-checks a prior refusal.
        """
        from sqlalchemy import update
        from server.audit import record_audit
        from server.db.clock import db_utc_now
        from server.db.models import Initiative, InitiativeArtifact

        out = await self.ready_merge(repo, int(pr_number))
        armed = bool(out.get("autoMergeArmed"))
        record = dict(gate) if armed else {**gate, "outcome": "refused"}
        async with db_session() as db:
            await db.execute(update(Initiative).where(
                Initiative.id == initiative_id).values(last_auto_gate=record))
            if armed:
                await db.execute(update(InitiativeArtifact).where(
                    InitiativeArtifact.id == artifact_id).values(
                        auto_merge_armed_at=db_utc_now()))
                await record_audit(
                    db=db, type="sdlc.gate.auto_resolve", identity="sdlc-synthesizer",
                    detail={"initiativeId": initiative_id, "artifactId": artifact_id,
                            "gate": "artifact.merge", "tolerance": gate.get("tolerance"),
                            "repo": repo, "pr": int(pr_number),
                            "alreadyArmed": bool(out.get("alreadyArmed"))})
            await db.commit()
        if not armed:
            return {"armed": False, "error": str(out.get("error") or "")}
        return {"armed": True, "error": ""}

    async def _sdlc_update_artifact(self, artifact_id: str, **fields) -> None:
        """Update an InitiativeArtifact (PR-metadata enrichment: pr_number/url/sha)."""
        if not fields:
            return
        from sqlalchemy import update
        from server.db.models import InitiativeArtifact
        async with db_session() as db:
            await db.execute(update(InitiativeArtifact).where(
                InitiativeArtifact.id == artifact_id).values(**fields))
            await db.commit()

    async def _sdlc_default_branch(self, repo: str) -> str:
        """The repo's default branch (``main``/``master``) — THE resolver for
        every spawn path in this class (backlog, pr-doctor consolidation, sdlc).
        Never hardcode ``master`` (the prompts warn); ``resolve_default_branch``
        already degrades to it off the loop and never raises."""
        from server.pm.map_changes import resolve_default_branch
        return await resolve_default_branch(repo)

    async def _sdlc_spawn_synth(self, ini: dict, kind: str):
        """Spawn a de-duped spec/plan session for *ini*, seeding the prompt with
        the upstream artifact's committed content read off ``origin/<default>``.

        Mirrors ``_backlog_spawn``: healthy-account gate, ensure_clone off the
        loop, ``_resolve_spawn_model`` for the model, and the same create-kwargs shape
        through the de-dup-safe context spawner (origin_ref=``<slug>:<kind>``).
        Returns the SessionRecord or None when no account has headroom (retry
        next tick)."""
        from server.sdlc.prompts import (
            artifact_path, build_plan_prompt, build_spec_prompt)
        repo = str(ini.get("repo") or "")
        slug = str(ini.get("slug") or "")
        if not repo or not slug:
            return None
        if kind not in ("spec", "plan"):  # pragma: no cover — loop only asks these
            return None
        # Engine FIRST, before any account, network or disk work. Two reasons,
        # and ``_backlog_spawn`` already moved its own check here for both:
        # the artifact instructions state a commit trailer (the one
        # engine-specific line in them), and a refusal must COST nothing — this
        # ran an account probe, a full ``ensure_clone`` and a remote branch
        # listing ahead of the policy check, and repeated all three every tick an
        # out-of-policy origin was ticked.
        plan = await self._sdlc_synth_ctx.launch_plan_or_refuse(f"{slug}:{kind}")
        if plan is None:
            return None
        engine, _launch_config = plan
        account = await self._automation_account_for(
            self._sdlc_synth_ctx, f"{slug}:{kind}", engine=engine)
        if account is None:
            return None
        _mode, config = await self._sdlc_synth_read_config()
        url = f"https://github.com/{repo}.git"
        cwd = await asyncio.to_thread(
            gitrepos.ensure_clone, await self._effective_repo_root(), repo, url)
        default_branch = await self._sdlc_default_branch(repo)
        upstream = artifact_path(slug, "intent" if kind == "spec" else "spec")
        # Epic-adopted initiatives (#2159) enter the chain directly at Design —
        # the intake stage that would have written intent.md never ran, so
        # there is nothing on disk to read. The plan stage needs no equivalent
        # branch: by then the design-stage session has committed a real spec.md.
        epic_upstream: tuple[str, str] | None = None
        if kind == "spec" and ini.get("origin") == "epic-adoption":
            epic_upstream = await self._sdlc_epic_upstream_text(
                ini.get("epic_repo"), ini.get("epic_number"))

        def build(cwd: str, default_branch: str) -> str:
            if epic_upstream is not None:
                content = epic_upstream[0]
            else:
                content = self._sdlc_show_committed_file(
                    cwd, f"origin/{default_branch}", upstream)
            if kind == "spec":
                const_path = ".specify/memory/constitution.md"
                raw_const_text = self._sdlc_show_committed_file(
                    cwd, f"origin/{default_branch}", const_path)
                const_text = (None if raw_const_text.startswith(_SDLC_UNREADABLE_PREFIX)
                             else raw_const_text)
                return build_spec_prompt(
                    content, [], slug=slug, repo=repo, default_branch=default_branch,
                    engine=engine, constitution=const_text, constitution_path=const_path)
            return build_plan_prompt(
                content, slug=slug, repo=repo, default_branch=default_branch,
                engine=engine)

        prompt = await asyncio.to_thread(build, cwd, default_branch)
        detail: dict = {"initiative": slug, "kind": kind, "engine": engine.value}
        summary = f"{ini.get('title') or slug}  ({kind})"
        choice = await self._resolve_spawn_model(engine, account, config, summary)
        model, reasoning_effort = choice.model, choice.reasoning_effort
        detail.update(choice.detail)
        rec = await self._sdlc_synth_ctx.spawn_session(
            origin_ref=f"{slug}:{kind}",
            dedupe_key=f"{slug}:{kind}",
            repo=repo,
            cwd=cwd,
            account=account,
            engine=engine,
            name=f"sdlc {kind} {slug}",
            initial_prompt=prompt,
            model=model,
            reasoning_effort=reasoning_effort,
            detail=detail,
        )
        if rec is not None and epic_upstream is not None:
            # Dynamic attribute, not a SessionRecord field: it never needs to
            # persist on the session itself, only to reach the artifact-index
            # write immediately below it in the synthesizer loop (see
            # ``_sdlc_record_artifact``'s ``upstream_ref`` kwarg).
            rec.upstream_ref = epic_upstream[1]
        return rec

    async def _sdlc_epic_upstream_text(
            self, epic_repo: str | None, epic_number: int | None,
    ) -> tuple[str, str] | None:
        """Epic body + its direct sub-issues' bodies, off the GitHub mirror —
        the substitute upstream for an epic-adopted initiative's spec stage
        (#2159), which has no committed ``intent.md`` to read. Returns
        ``(markdown, "owner/repo#N")``, or ``None`` when there is no pointer or
        the epic is not (yet) mirrored — the caller then falls back to the
        normal committed-file read."""
        if not epic_repo or epic_number is None:
            return None
        from sqlalchemy import select as sa_select
        from server.db.models import WorkItem
        async with db_session() as db:
            epic = (await db.execute(sa_select(WorkItem).where(
                WorkItem.repo == epic_repo, WorkItem.number == epic_number,
            ))).scalar_one_or_none()
            if epic is None:
                return None
            children = (await db.execute(sa_select(WorkItem).where(
                WorkItem.parent_work_item_id == epic.id,
            ).order_by(WorkItem.number))).scalars().all()
        ref = f"{epic_repo}#{epic_number}"
        parts = [
            f"(upstream: epic {ref}; no intent.md exists — this initiative was "
            "adopted directly from the epic, so the spec is seeded from the "
            "mirrored epic and its sub-issues instead)",
            "", f"# {epic.title or ref}", "", epic.body or "_(no body)_",
        ]
        for child in children:
            parts += ["", f"## #{child.number} {child.title or ''}".rstrip(),
                     child.body or "_(no body)_"]
        return "\n".join(parts), ref

    async def _sdlc_spawn_materialize(self, ini: dict):
        """Spawn a de-duped decompose session for a merged plan (spec 003 §7b).

        Same shape as ``_sdlc_spawn_synth`` — engine plan first (a refusal must
        cost no account probe and no clone), then account, clone and the merged
        artifact read off ``origin/<default>`` — but the deliverable is a JSON
        decomposition in the final message, not a PR: nothing is created on
        GitHub until a human accepts the ``MaterializationProposal``. Chains the
        ingest that turns that message into the proposal row.

        Returns None — spawning nothing — when a decompose session for this plan
        is already live. ``spawn_session`` would hand back that SAME session on
        the dedupe key, and the caller would then chain a SECOND ingest onto it
        and re-emit; asking first makes a tick during the decompose a no-op.

        The key is per ATTEMPT (``<slug>:materialize:<n>``, n = proposals so far,
        any status) — C4-R15. With one key per initiative, a REJECTED proposal's
        finished session still matched ``spawn_session``'s dedupe, which handed it
        straight back; the chained ingest then re-harvested its stale transcript
        into a byte-identical pending proposal, so the rejection never stuck. A
        new attempt gets a new key, while a still-running attempt dedupes exactly
        as before because the live check and the spawn use the SAME key."""
        from server.pm.materialize import build_materialize_prompt
        from server.sdlc.prompts import artifact_path
        repo = str(ini.get("repo") or "")
        slug = str(ini.get("slug") or "")
        if not repo or not slug:
            return None
        async with db_session() as db:
            attempts = await self._sdlc_materialization_attempts(
                db, str(ini.get("id") or ""))
        # `.total`, never `.budget`: the key must be unique over the initiative's
        # whole history. A retry (#1582) resets the BUDGET, and keying on that
        # would re-mint `<slug>:materialize:0` — whose finished session the dedupe
        # would hand straight back, re-ingesting a transcript this tick did not
        # produce (C4-R15). The total only ever goes up.
        origin_ref = f"{slug}:materialize:{attempts.total}"
        # Both no-op cases up front, before the account probe and the clone: a
        # refusal must cost nothing, and BOTH conditions persist across ticks.
        prior = await self._sdlc_dedupe_session_for(origin_ref)
        if prior is not None:
            prior_id, prior_status = prior
            from server.pm.desired_state import LIVE_SESSION_STATUSES
            if prior_status in LIVE_SESSION_STATUSES:
                return None  # still decomposing (C4-R14) — a silent no-op
            # Finished, but still what spawn_session's dedupe would hand back, and
            # the attempt number has not moved (its ingest never wrote a proposal).
            # Chaining onto it would re-harvest a transcript this tick did not
            # produce (C4-R15). Latched: the condition holds until the attempt
            # moves, so an unlatched emit would repeat on every tick forever.
            seen: set[str] | None = getattr(self, "_materialize_deduped_keys", None)
            if seen is None:
                seen = self._materialize_deduped_keys = set()
            if origin_ref not in seen:
                seen.add(origin_ref)
                await self._sdlc_emit(
                    "warn", f"{slug}: the decompose session {prior_id} for this "
                            "attempt has finished without a proposal — not "
                            "re-running it; review that session",
                    kind="materialization_spawn_deduped", target=slug,
                    session_id=prior_id)
            return None
        plan = await self._sdlc_synth_ctx.launch_plan_or_refuse(origin_ref)
        if plan is None:
            return None
        engine, _launch_config = plan
        account = await self._automation_account_for(
            self._sdlc_synth_ctx, origin_ref, engine=engine)
        if account is None:
            return None
        _mode, config = await self._sdlc_synth_read_config()
        url = f"https://github.com/{repo}.git"
        cwd = await asyncio.to_thread(
            gitrepos.ensure_clone, await self._effective_repo_root(), repo, url)
        default_branch = await self._sdlc_default_branch(repo)
        path = artifact_path(slug, "plan")
        plan_markdown = await asyncio.to_thread(
            self._sdlc_show_committed_file, cwd, f"origin/{default_branch}", path)
        if plan_markdown.startswith(_SDLC_UNREADABLE_PREFIX):
            # Seeding the "read that file yourself" fallback is how the spec/plan
            # stages survive a stale clone, but a decompose session cannot: with
            # no plan text it would invent a decomposition from the slug, and a
            # human would be asked to accept fiction. Skip loudly instead — but
            # warn ONCE per slug (as the loop's `materialization_unwired` warn
            # does): the condition persists, so every tick would re-emit it.
            # Lazily created as well as set in __init__: the seam tests build the
            # orchestrator with __new__ (no __init__ runs), so reading the
            # attribute directly would AttributeError there.
            warned: set[str] | None = getattr(
                self, "_materialize_unreadable_slugs", None)
            if warned is None:
                warned = self._materialize_unreadable_slugs = set()
            if slug not in warned:
                warned.add(slug)
                await self._sdlc_emit(
                    "warn", f"cannot decompose {slug}: {path} is unreadable on "
                            f"origin/{default_branch}",
                    kind="materialization_plan_unreadable", target=slug,
                    detail={"path": path, "ref": f"origin/{default_branch}"})
            return None
        # The decomposition contract lives in the prompt builder (one source of
        # truth); only the operational shape of THIS session is added here.
        prompt = build_materialize_prompt(slug, repo, plan_markdown) + (
            f"\n\nThe plan above is `{path}` on `origin/{default_branch}`. Do not "
            "change any file, do not commit, and do not open a pull request: this "
            "session's only deliverable is the fenced JSON, which must be the last "
            "thing in your final message."
        )
        detail: dict = {"initiative": slug, "kind": "materialize",
                        "engine": engine.value}
        summary = f"{ini.get('title') or slug}  (decompose)"
        # Same model policy as the spec/plan sessions — one `default_model`
        # setting covers every session this automation spawns.
        choice = await self._resolve_spawn_model(engine, account, config, summary)
        model, reasoning_effort = choice.model, choice.reasoning_effort
        detail.update(choice.detail)
        rec = await self._sdlc_synth_ctx.spawn_session(
            origin_ref=origin_ref,
            dedupe_key=origin_ref,
            repo=repo,
            cwd=cwd,
            account=account,
            engine=engine,
            name=f"sdlc materialize {slug}",
            initial_prompt=prompt,
            model=model,
            reasoning_effort=reasoning_effort,
            detail=detail,
        )
        if rec is None:
            return None
        # No post-spawn identity guard: ``_sdlc_dedupe_session_for`` above runs the
        # SAME query ``spawn_session``'s find-or-create does (origin + key + not
        # ended), so reaching this line means the dedupe found nothing and ``rec``
        # is this call's own session. A second check here would be dead code.
        # Harvest wiring: without the chain the session finishes and its JSON is
        # never read (the bug the classify chain was added for).
        self._spawn(self._sdlc_materialize_chain_ingest(rec.id, slug),
                    name=f"sdlc-materialize-ingest-{slug}")
        return rec

    async def _sdlc_materialize_chain_ingest(
            self, session_id: str, slug: str, *,
            attempts: int = _MATERIALIZE_SETTLE_ATTEMPTS,
            delay: float = 30.0) -> int:
        """Wait (bounded) for a decompose session to settle, then ingest its JSON.

        Fire-and-forget: nothing awaits this task, so every failure is absorbed
        here — an escaping exception would surface only as a 'never retrieved'
        log and the initiative would sit parked with no explanation."""
        try:
            if not await self._await_session_settled(session_id, attempts=attempts,
                                                     interval_s=delay):
                # Say so and stop. NOT `blocked`: the session may still be alive
                # and about to answer, and blocking would take the initiative out
                # of the engine's hands over a budget this chain owns, not a
                # decision anyone made (C4-R20).
                await self._sdlc_emit(
                    "warn", f"the decompose session for {slug} has not finished "
                            "within the ingest budget — its decomposition will not "
                            "be read; re-run it once it settles",
                    kind="materialization_ingest_timeout", target=slug,
                    session_id=session_id, detail={"attempts": attempts})
                return 0
            written = await self._sdlc_materialize_ingest(session_id, slug)
            # Same shape as the classify chain, same fix: `server/pm/materialize.py`
            # tells this session to "Return ONLY a JSON object", so it too ends its
            # turn at `done` with no completion signal. Its work_class is
            # `development`, so it never lifts tabs — it just rests at "Your turn"
            # forever, and since `_persist_status` releases the driver only on
            # `complete`, every finished decompose session pinned a live `claude`
            # process. `written` is 1 only for a parsed, non-duplicate pending
            # proposal; a parse failure returns 0 and stays visible for a human.
            if written:
                await self._certify_harvested_complete(session_id)
            return written
        except asyncio.CancelledError:
            raise
        except Exception:
            log.warning("sdlc_materialize.chain_ingest_failed session=%s slug=%s",
                        session_id, slug, exc_info=True)
            await self._sdlc_emit("warn", f"could not ingest the decomposition for {slug}",
                                  kind="materialization_ingest_failed", target=slug,
                                  session_id=session_id)
            return 0

    async def _sdlc_dedupe_session_for(self, origin_ref: str) -> tuple[str, str] | None:
        """``(id, status)`` of the session ``spawn_session`` would hand back for
        *origin_ref*, or None — deliberately the SAME query its find-or-create
        runs (this automation's origin, the key, and not ended).

        The caller splits it two ways. A status in the live set (``desired_state``,
        the app's one definition of "a session holds this") means the decompose is
        still running and the tick is a silent no-op — C4-R14, deliberately NOT
        ``_existing_session``'s "not ended" rule, which would let a REJECTED
        proposal's ``complete`` session block every future decompose. Any other
        status means the dedupe WOULD return a finished session for an attempt
        that never produced a proposal, which must not be re-chained (C4-R15)."""
        from sqlalchemy import select
        from server.db.models import INACTIVE_SESSION_STATUSES, Session as DbSession
        async with db_session() as db:
            row = (await db.execute(
                select(DbSession.id, DbSession.status).where(
                    DbSession.origin == self._sdlc_synth_ctx.automation_id,
                    DbSession.origin_ref == origin_ref,
                    DbSession.status.not_in(INACTIVE_SESSION_STATUSES)))).first()
        return (str(row[0]), str(row[1] or "")) if row is not None else None

    async def _pm_issue_decision(self, work_item_id: str, decision: dict) -> dict:
        from server.db.models import WorkItem
        from server.pm.issue_disposition import IssueDecision, apply
        from server.pm.repo_project import gather_repo_ownership_snapshot
        async with db_session() as preflight:
            item = await preflight.get(WorkItem, work_item_id)
            repos = [item.repo] if item is not None and item.repo else []
        ownership = await gather_repo_ownership_snapshot(repos)
        # Serialize decisions on one issue within the authority, including the
        # preflight. A queued request then sees the updated mirrored version.
        locks = getattr(self, "_issue_decision_locks", None)
        if locks is None:
            from weakref import WeakValueDictionary
            self._issue_decision_locks: WeakValueDictionary[str, asyncio.Lock] = WeakValueDictionary()
            locks = self._issue_decision_locks
        lock = locks.setdefault(work_item_id, asyncio.Lock())
        async with lock, db_session() as db:
            src = await db.get(WorkItem, work_item_id)
            if src is None or src.kind != "issue":
                return {"ok": False, "step": "load", "error": "Issue not found"}
            return await apply(db, src=src, decision=IssueDecision.model_validate(decision),
                               fetch=self._pm_sync_fetch_projects,
                               mutate=self._pm_reconcile_mutate, now=self._pm_sync_now_utc(), ownership=ownership)

    async def _pm_remove_dependency(self, work_item_id: str, blocker_ref: str) -> dict:
        """Delete one blocked-by edge on GitHub (roadmap spec §8, #1472).

        THE seam the API calls, for the same reason as ``_sdlc_materialize_apply``:
        the router decides a human asked, this owns the transport
        (``_pm_reconcile_mutate``) and the journal. A failure is data, not an
        exception — the route turns it into a 502 and the row stays blocked."""
        from sqlalchemy import select
        from server.db.models import WorkItem
        from server.pm.dep_remove import remove
        from server.pm.repo_project import gather_repo_ownership_snapshot
        async with db_session() as preflight:
            item = await preflight.get(WorkItem, work_item_id)
            repos = [item.repo] if item is not None and item.repo else []
        ownership = await gather_repo_ownership_snapshot(repos)
        now = self._pm_sync_now_utc()
        async with db_session() as db:
            src = (await db.execute(select(WorkItem).where(
                WorkItem.id == work_item_id))).scalar_one_or_none()
            if src is None:
                return {"ok": False, "step": "load", "error": f"no such work item: {work_item_id}"}
            result = await remove(db, src=src, blocker_ref=blocker_ref,
                                  mutate=self._pm_reconcile_mutate, now=now, ownership=ownership)
            await db.commit()
        return result

    async def _sdlc_materialize_apply(self, proposal_id: str) -> dict:
        """Apply an accepted MaterializationProposal (spec 003 §7b, human gate).

        THE seam the API calls: the router decides that a human said yes, this
        owns the GitHub transport (``_pm_reconcile_mutate``, the App/PAT ladder
        every other 003 write uses) and the activity feed. Returns the apply
        result dict unchanged — a failure is data, not an exception, because the
        proposal stays pending and resumable.

        SERIALISED PER PROPOSAL (C4-R17). The apply's resume key is the ``created``
        map it commits between calls, so two concurrent runs both read "nothing
        created yet" and both create the epic: a duplicate the journal cannot undo.
        A second caller is REFUSED rather than queued — waiting would apply the
        same proposal twice in a row, and the honest answer to "is this running?"
        is more use to the human than a reply ten GitHub calls later.

        The lock dict is created lazily as well as in ``__init__``: the seam tests
        build the orchestrator with ``__new__`` (no constructor runs), exactly as
        ``_materialize_unreadable_slugs`` is handled."""
        locks: dict[str, asyncio.Lock] | None = getattr(
            self, "_materialize_apply_locks", None)
        if locks is None:
            locks = self._materialize_apply_locks = {}
        lock = locks.setdefault(proposal_id, asyncio.Lock())
        if lock.locked():
            # No DB work at all on this path: the answer does not depend on any
            # row, and a read here would only widen the window it is closing.
            return {"ok": False, "step": "in_flight",
                    "error": "an apply for this proposal is already running"}
        try:
            async with lock:
                return await self._sdlc_materialize_apply_locked(proposal_id)
        finally:
            # Nobody ever waits on this lock (a second caller is refused above),
            # so it is free the moment the run ends — drop it rather than keep one
            # per proposal ever applied for the daemon's whole life.
            if not lock.locked():
                locks.pop(proposal_id, None)

    async def _sdlc_materialize_apply_locked(self, proposal_id: str) -> dict:
        """The apply itself; the caller holds this proposal's lock (C4-R17)."""
        from sqlalchemy import select
        from server.db.models import Initiative, MaterializationProposal
        from server.pm.materialize_apply import apply
        from server.pm.repo_project import gather_repo_ownership_snapshot
        async with db_session() as preflight:
            repo = await preflight.scalar(select(Initiative.repo).join(
                MaterializationProposal, MaterializationProposal.initiative_id == Initiative.id
            ).where(MaterializationProposal.id == proposal_id))
        ownership = await gather_repo_ownership_snapshot([repo] if repo else [])
        now = self._pm_sync_now_utc()
        async with db_session() as db:
            proposal = (await db.execute(select(MaterializationProposal).where(
                MaterializationProposal.id == proposal_id))).scalar_one_or_none()
            if proposal is None:
                return {"ok": False, "step": "load",
                        "error": f"no such proposal: {proposal_id}"}
            slug = str((await db.execute(select(Initiative.slug).where(
                Initiative.id == proposal.initiative_id))).scalars().first() or "")
            result = await apply(db, proposal, mutate=self._pm_reconcile_mutate,
                                 now=now, ownership=ownership)
        if result.get("ok"):
            epic = (result.get("epic") or {}).get("number")
            await self._sdlc_emit(
                "info", f"materialized {slug}: epic #{epic} with "
                        f"{result.get('tasks')} tasks",
                kind="materialized", target=slug,
                # parkedEdges is part of the outcome, not a detail: a chain with a
                # dropped edge looks identical on the board otherwise.
                detail={"epic": epic, "tasks": result.get("tasks"),
                        "edges": result.get("edges"),
                        "parkedEdges": result.get("parkedEdges")})
        else:
            await self._sdlc_emit(
                "warn", f"could not materialize {slug}: {result.get('error')}",
                kind="materialization_failed", target=slug,
                detail={"step": result.get("step"), "error": result.get("error")})
        return result

    @staticmethod
    async def _sdlc_materialization_attempts(db, initiative_id: str) -> "MaterializeAttempts":
        """Both decomposition counts for this initiative, as a ``MaterializeAttempts``.

        ``total`` is every proposal row, ANY status — the attempt number in the
        decompose session's dedupe key (C4-R15). Counting every status is the
        point: a rejected attempt must still bump the key, or its finished session
        is handed back by the dedupe and re-ingested.

        ``budget`` is that total net of ``Initiative.materialize_retry_baseline``,
        which is what a human's "Decompose again" writes (#1582) — so the
        exhaustion gate can be reset without deleting a row the dedupe key
        depends on. ONE query for both; the derivation itself lives with
        ``MATERIALIZE_MAX_ATTEMPTS`` so the loop and the two API readers share it."""
        from sqlalchemy import func, select
        from server.automations.sdlc_synthesizer import MaterializeAttempts
        from server.db.models import Initiative, MaterializationProposal
        total = int((await db.execute(
            select(func.count()).select_from(MaterializationProposal).where(
                MaterializationProposal.initiative_id == initiative_id))).scalar() or 0)
        baseline = (await db.execute(select(Initiative.materialize_retry_baseline).where(
            Initiative.id == initiative_id))).scalars().first()
        return MaterializeAttempts.of(total, baseline)

    @staticmethod
    async def _sdlc_pending_materialization_id(db, initiative_id: str) -> str | None:
        """Id of the MaterializationProposal awaiting the human gate, or None.

        ONE query behind both users of "is this plan already decomposed and
        waiting?" — the loop's spawn gate and the ingest's duplicate guard. Two
        copies would drift, and the two directions of that drift are a second
        decompose session and a second proposal row for one initiative."""
        from sqlalchemy import select
        from server.db.models import MaterializationProposal
        return (await db.execute(select(MaterializationProposal.id).where(
            MaterializationProposal.initiative_id == initiative_id,
            MaterializationProposal.status == "pending"))).scalars().first()

    async def _sdlc_has_pending_materialization(self, initiative_id: str) -> bool:
        """Loop seam: does this initiative already have a proposal to review?

        This — not ``Initiative.status`` — is the materialize park signal: the
        plan Propose parks every initiative at ``awaiting_human`` long before the
        decomposition exists (C4-R13a)."""
        async with db_session() as db:
            return (await self._sdlc_pending_materialization_id(
                db, initiative_id)) is not None

    async def _sdlc_materialization_attempts_for(self, initiative_id: str) -> "MaterializeAttempts":
        """Loop seam: this initiative's decomposition counts (``MaterializeAttempts``).

        The loop's neighbour of ``_sdlc_has_pending_materialization`` and the same
        read the spawn key uses (``_sdlc_materialization_attempts``, one query for
        both) — a decompose that keeps failing to parse must stop after
        ``MATERIALIZE_MAX_ATTEMPTS`` rather than burning a session every tick."""
        async with db_session() as db:
            return await self._sdlc_materialization_attempts(db, initiative_id)

    async def _sdlc_materialize_ingest(self, session_id: str, slug: str) -> int:
        """Turn a decompose session's output into ONE pending MaterializationProposal.

        Idempotent on the pending proposal, not on the session: a re-ingest (or a
        second decompose session for the same plan) must never leave a human two
        proposals to choose between.

        A parse failure records a REJECTED proposal instead of blocking the
        initiative (C4-R19b). Blocking was a dead end: ``next_action`` answers
        ``NeedsHuman`` for a blocked initiative, so one unreadable final message
        took the plan out of the loop until a human noticed and un-blocked it by
        hand. The rejected row is both the record of the failed attempt and what
        moves the attempt key, so the next tick decomposes again — bounded by
        ``MATERIALIZE_MAX_ATTEMPTS`` in the loop."""
        from sqlalchemy import select
        from server.db.models import Initiative, MaterializationProposal
        from server.pm.materialize import (
            MaterializationParseError, parse_materialization_output)
        text = await self._chained_session_output_text(session_id)
        async with db_session() as db:
            initiative_id = (await db.execute(select(Initiative.id).where(
                Initiative.slug == slug))).scalars().first()
        if initiative_id is None:
            log.warning("sdlc_materialize.ingest: no initiative %s", slug)
            return 0
        try:
            decomposition = parse_materialization_output(text)
        except MaterializationParseError as e:
            async with db_session() as db:
                db.add(MaterializationProposal(
                    initiative_id=initiative_id,
                    status="rejected",
                    session_id=session_id,
                    payload={"source_session": session_id, "parse_error": str(e)},
                    rationale=f"parse failed: {e}"[:500],
                    resolved_at=self._pm_sync_now_utc()))
                await db.commit()
            await self._sdlc_emit("warn", f"could not read a decomposition for {slug}",
                                  kind="materialization_parse_failed", target=slug,
                                  session_id=session_id, detail={"error": str(e)})
            return 0
        async with db_session() as db:
            dup = await self._sdlc_pending_materialization_id(db, initiative_id)
            if dup is not None:
                await self._sdlc_emit(
                    "info", f"{slug} already has a materialization proposal awaiting review",
                    kind="materialization_duplicate_ignored", target=slug,
                    session_id=session_id)
                return 0
            db.add(MaterializationProposal(
                initiative_id=initiative_id,
                status="pending",
                session_id=session_id,
                payload={
                    "epic_title": decomposition.epic_title,
                    "epic_body": decomposition.epic_body,
                    "tasks": [{"title": t.title, "body": t.body,
                               "depends_on": list(t.depends_on)}
                              for t in decomposition.tasks],
                    "source_session": session_id,
                },
                # The prose the session wrote before the fence — the only place
                # its reasoning survives, and what the human reads next to the
                # task list.
                rationale=(text.split("```", 1)[0].strip()[:500] or None),
            ))
            await db.commit()
        log.info("sdlc_materialize.ingest: slug=%s tasks=%d session=%s",
                 slug, len(decomposition.tasks), session_id)
        return 1

    async def _sdlc_emit(self, level: str, summary: str, **kw) -> None:
        """Best-effort activity event on the synthesizer's feed (the ingest runs
        outside the loop's own try/except, so it swallows its own emit errors)."""
        try:
            await self._sdlc_synth_ctx.emit(level, summary, **kw)
        except Exception:
            log.debug("sdlc_materialize.emit_failed", exc_info=True)

    @staticmethod
    def _sdlc_show_committed_file(cwd: str, ref: str, path: str) -> str:
        """Contents of *path* at *ref* in the clone at *cwd* (sync — call off-loop).

        Falls back to an instruction to read the file in-repo when unreadable, so
        a stale clone can never block the stage — the artifact is committed on the
        default branch by the time the engine proposes the next stage."""
        try:
            out = subprocess.run(
                ["git", "-C", cwd, "show", f"{ref}:{path}"],
                capture_output=True, text=True, timeout=30, check=False)
            if out.returncode == 0 and out.stdout.strip():
                return out.stdout
        except Exception:
            log.debug("sdlc.show_artifact_failed", exc_info=True)
        return (f"{_SDLC_UNREADABLE_PREFIX} `{path}` from `{ref}` — read that file "
                "from the repository before starting)")

    async def _sdlc_pr_lookup(self, art: dict) -> dict | None:
        """The artifact session's PR as the enrichment dict shape, or None.

        Resolves the artifact's ``session_id`` to its repo + branch(es) and reads
        the PR-poller cache — the SAME session→PR source of truth
        ``_backlog_pr_status_for`` uses (live record first, then the DB row's
        ``branch``/``authored_branches``). No network client: an artifact whose PR
        the poller has not cached yet simply returns None and enriches next tick.
        state ``merged`` carries the merge-commit sha (the enrich writer's key)."""
        sid = art.get("session_id")
        if not sid:
            return None
        from sqlalchemy import select as sa_select
        repo: str | None = None
        branches: list[str] = []
        rec = self._records.get(sid)
        if rec is not None:
            repo = rec.repo
            if rec.branch:
                branches.append(rec.branch)
            branches.extend(getattr(rec, "authored_branches", None) or [])
        else:
            async with db_session() as db:
                row = (await db.execute(sa_select(
                    DbSession.repo, DbSession.branch, DbSession.authored_branches,
                ).where(DbSession.id == sid))).first()
            if row is not None:
                repo = row.repo
                if row.branch:
                    branches.append(row.branch)
                branches.extend(row.authored_branches or [])
        if not repo:
            return None
        for branch in dict.fromkeys(branches):
            info = self._pr_poller.cached(repo, branch)
            if info is None:
                continue
            state = "merged" if info.merged else info.state
            sha = info.merge_commit_sha or None
            return {"number": info.number, "url": info.url,
                    "state": state, "sha": sha if state == "merged" else None}
        return None

    async def _sdlc_synth_tick_loop(self, interval: float) -> None:
        """Periodic driver for the synthesizer loop (mirrors _sdlc_intake_tick_loop)."""
        while True:
            await self._sdlc_synth_tick_once()
            await asyncio.sleep(interval)

    async def _sdlc_synth_tick_once(self) -> None:
        """One synthesizer tick + an enabled-only ``last_active_at`` heartbeat.
        Best-effort — neither the tick nor the heartbeat may crash the loop."""
        await self._sdlc_synth_fold_stored_mode()
        if not await self._schedule_allows_tick("sdlc-synthesizer"):
            return
        try:
            await self._sdlc_synthesizer_loop.tick()
        except Exception:  # pragma: no cover — tick() already swallows; belt+braces
            log.warning("sdlc_synthesizer.tick_loop_error", exc_info=True)
        try:
            mode, _ = await self._sdlc_synth_read_config()
            if mode != "off":
                await self._bump_automation_active("sdlc-synthesizer")
        except Exception:  # pragma: no cover — a heartbeat failure must not stall
            log.debug("sdlc_synthesizer.bump_active_failed", exc_info=True)

